  }
};

export const INITIAL_STATS = {
  mood: 80,
  hunger: 50,
  energy: 100
};

export const FOODS = [
  { id: 'biscuit', name: 'Handmade Biscuit', icon: '🍪', hungerBoost: 15 },
  { id: 'fish', name: 'Fresh Salmon', icon: '🐟', hungerBoost: 30 },
  { id: 'treat', name: 'Special Treat', icon: '🍬', hungerBoost: 10, moodBoost: 10 }
];

import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function generateJournalEntry(petName: string, stats: any, activity: string) {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Generate a short, poetic, and healing journal entry (max 50 words) from the perspective of a pet owner about their deceased pet named ${petName}. 
      The current interaction is: ${activity}. 
      The emotional tone should be nostalgic, warm, and comforting. Use Chinese language.`,
      config: {
        temperature: 0.9,
      }
    });
    return response.text?.trim() || "今天又想起了你，心里暖暖的。";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "记忆在微风中摇曳，你在远方守护着我。";
  }
}

import React, { useRef, useState } from 'react';

interface PixelatorProps {
  onComplete: (pixelData: string) => void;
}

export const Pixelator: React.FC<PixelatorProps> = ({ onComplete }) => {
  const [loading, setLoading] = useState(false);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const processImage = (file: File) => {
    setLoading(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        // Set dimensions for pixelation (32x32 standard)
        const size = 32;
        canvas.width = size;
        canvas.height = size;

        // Draw scaled down
        ctx.imageSmoothingEnabled = false;
        ctx.drawImage(img, 0, 0, size, size);

        // Enhance color slightly
        const imageData = ctx.getImageData(0, 0, size, size);
        const data = imageData.data;
        for (let i = 0; i < data.length; i += 4) {
          // Boost saturation for that game feel
          data[i] = Math.min(255, data[i] * 1.1);
          data[i+1] = Math.min(255, data[i+1] * 1.1);
          data[i+2] = Math.min(255, data[i+2] * 1.1);
        }
        ctx.putImageData(imageData, 0, 0);

        onComplete(canvas.toDataURL());
        setLoading(false);
      };
      img.src = e.target?.result as string;
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="flex flex-col items-center justify-center p-8 bg-white/40 rounded-3xl border-2 border-dashed border-amber-300">
      <canvas ref={canvasRef} className="hidden" />
      <p className="mb-4 text-amber-800 text-center font-medium">
        {loading ? "正在编织像素记忆..." : "上传一张它的照片，让我们在这里重逢"}
      </p>
      <input
        type="file"
        accept="image/*"
        onChange={(e) => e.target.files?.[0] && processImage(e.target.files[0])}
        className="hidden"
        id="pet-upload"
      />
      <label
        htmlFor="pet-upload"
        className="cursor-pointer bg-amber-400 hover:bg-amber-500 text-white px-8 py-3 rounded-full shadow-lg transition-all active:scale-95"
      >
        选择照片
      </label>
      <p className="mt-4 text-xs text-amber-600">支持 JPG/PNG • 像素化艺术风格</p>
    </div>
  );
};

