import React, { useState, useEffect, useCallback, useRef } from 'react';
import { PetStats, PetInfo, MapType, JournalEntry } from './types';
import { INITIAL_STATS, COLORS } from './constants';
import { Pixelator } from './components/Pixelator';
import { GameUI } from './components/GameUI';
import { generateJournalEntry } from './services/geminiService';
import { Moon, Sun, Sparkles, Wind, Info, BookOpen } from 'lucide-react';

const App: React.FC = () => {
  const [pet, setPet] = useState<PetInfo | null>(null);
  const [stats, setStats] = useState<PetStats>(INITIAL_STATS);
  const [currentMap, setCurrentMap] = useState<MapType>('HOME');
  const [isJournalOpen, setIsJournalOpen] = useState(false);
  const [journal, setJournal] = useState<JournalEntry[]>([]);
  const [isNight, setIsNight] = useState(false);
  const [petPosition, setPetPosition] = useState({ x: 50, y: 60 });
  const [petAnimation, setPetAnimation] = useState<'idle' | 'walking' | 'sleeping'>('idle');
  const [currentThought, setCurrentThought] = useState<string | null>(null);

  // Time management
  useEffect(() => {
    const hour = new Date().getHours();
    setIsNight(hour < 6 || hour > 19);

    // Decay stats over time
    const interval = setInterval(() => {
      setStats(prev => ({
        mood: Math.max(0, prev.mood - 0.5),
        hunger: Math.max(0, prev.hunger - 1),
        energy: isNight ? Math.min(100, prev.energy + 2) : Math.max(0, prev.energy - 0.5)
      }));
    }, 10000);

    return () => clearInterval(interval);
  }, [isNight]);

  // Pet Movement Simulation
  useEffect(() => {
    if (!pet || petAnimation === 'sleeping') return;

    const moveInterval = setInterval(() => {
      if (Math.random() > 0.7) {
        setPetAnimation('walking');
        const nextX = Math.max(20, Math.min(80, petPosition.x + (Math.random() * 20 - 10)));
        const nextY = Math.max(40, Math.min(75, petPosition.y + (Math.random() * 10 - 5)));
        setPetPosition({ x: nextX, y: nextY });
        setTimeout(() => setPetAnimation('idle'), 2000);
      }
    }, 5000);

    return () => clearInterval(moveInterval);
  }, [pet, petPosition, petAnimation]);

  const handlePetCreated = (pixelData: string) => {
    const name = prompt("给你的伙伴起个名字吧") || "我的宝贝";
    const newPet: PetInfo = {
      name,
      type: 'cat',
      pixelArt: pixelData
    };
    setPet(newPet);

    // Save initial journal entry
    const initialEntry = {
      date: new Date().toLocaleDateString(),
      content: `${name} 回到了它的新家，这里永远充满阳光和爱。`
    };
    setJournal([initialEntry]);
  };

  const handleFeed = async (food: any) => {
    if (!pet) return;
    setStats(prev => ({
      ...prev,
      hunger: Math.min(100, prev.hunger + food.hungerBoost),
      mood: Math.min(100, prev.mood + (food.moodBoost || 5))
    }));

    setCurrentThought(`*咬咬* 好吃！`);
    setTimeout(() => setCurrentThought(null), 3000);

    const entryText = await generateJournalEntry(pet.name, stats, `喂食了 ${food.name}`);
    setJournal(prev => [{ date: new Date().toLocaleDateString(), content: entryText }, ...prev]);
  };

  const handleInteraction = async (type: string) => {
    if (!pet) return;
    setStats(prev => ({ ...prev, mood: Math.min(100, prev.mood + 10) }));

    setCurrentThought(type === 'head' ? "呼噜噜..." : "最喜欢你了~");
    setTimeout(() => setCurrentThought(null), 3000);
  };

  const theme = isNight ? COLORS.night : COLORS.day;

  return (
    <div className={`fixed inset-0 transition-colors duration-1000 ${theme.bg} overflow-hidden font-sans`}>
      {/* Background Ambience */}
      <div className="absolute inset-0 opacity-20 pointer-events-none">
        {isNight ? (
          <div className="w-full h-full bg-[radial-gradient(circle_at_50%_50%,#312e81,transparent)]" />
        ) : (
          <div className="w-full h-full bg-[radial-gradient(circle_at_50%_20%,#fef08a,transparent)]" />
        )}
      </div>

      {!pet ? (
        <div className="flex flex-col items-center justify-center h-full px-6 text-center">
          <div className="mb-8 animate-float">
            <div className="bg-amber-100 p-6 rounded-full">
              <Sparkles className="w-16 h-16 text-amber-500" />
            </div>
          </div>
          <h1 className="text-3xl font-bold text-amber-900 mb-2">彩虹桥：永恒的陪伴</h1>
          <p className="text-amber-700/80 mb-8 max-w-sm">那些离开的伙伴并未远去，它们在这里，以另一种方式继续陪伴着你。</p>
          <Pixelator onComplete={handlePetCreated} />

          <div className="mt-12 text-amber-600/60 flex items-center gap-2 cursor-pointer hover:text-amber-600 transition-colors">
            <Info className="w-4 h-4" />
            <span className="text-sm">了解这个纪念计划</span>
          </div>
        </div>
      ) : (
        <div className="relative w-full h-full">
          {/* Environment Elements */}
          <div className="absolute top-8 left-8 flex items-center gap-2 text-amber-900/60">
             {isNight ? <Moon className="w-6 h-6" /> : <Sun className="w-6 h-6" />}
             <span className="font-medium">{new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
          </div>

          <div className="absolute top-8 right-8 text-right">
            <h2 className="text-xl font-bold text-amber-900">{pet.name}</h2>
            <p className="text-xs text-amber-600">正在{currentMap === 'HOME' ? '惬意休息' : '探索世界'}</p>
          </div>

          {/* Main Scene Area */}
          <div className="relative w-full h-full">
             {/* Home Scene */}
             {currentMap === 'HOME' && (
                <div className="absolute inset-0 flex items-center justify-center">
                   {/* Pixelated Floor/Rug */}
                   <div className="w-[80%] h-32 bg-amber-100/50 rounded-[50%] absolute bottom-[20%] blur-xl" />

                   {/* Scene Decorations */}
                   <div className="absolute bottom-[25%] left-[20%] w-16 h-16 bg-white/40 rounded-lg backdrop-blur-sm border border-white/50 flex items-center justify-center shadow-inner">
                      <span className="text-2xl">🧸</span>
                   </div>
                   <div className="absolute bottom-[28%] right-[15%] w-20 h-24 bg-white/40 rounded-lg backdrop-blur-sm border border-white/50 flex flex-col items-center justify-center p-2 shadow-inner">
                      <img src={pet.originalArt || pet.pixelArt} className="w-full h-full object-cover rounded border border-amber-200" alt="Pet Memorial" />
                   </div>
                </div>
             )}

             {/* Forest Scene */}
             {currentMap === 'FOREST' && (
                <div className="absolute inset-0">
                   <div className="absolute bottom-1/4 w-full flex justify-around opacity-40">
                      {[1,2,3,4].map(i => <Wind key={i} className={`w-8 h-8 text-emerald-600 animate-pulse`} style={{ animationDelay: `${i}s` }} />)}
                   </div>
                   {/* Memory Particles */}
                   {[...Array(5)].map((_, i) => (
                     <div 
                      key={i} 
                      className="absolute w-2 h-2 bg-yellow-300 rounded-full blur-[2px] animate-bounce"
                      style={{ 
                        left: `${20 + i * 15}%`, 
                        top: `${40 + (i % 3) * 10}%`,
                        animationDelay: `${i * 0.5}s`
                      }} 
                     />
                   ))}
                </div>
             )}

             {/* The Pet Sprite */}
             <div 
                className="absolute transition-all duration-2000 ease-in-out cursor-pointer"
                style={{ left: `${petPosition.x}%`, top: `${petPosition.y}%`, transform: 'translate(-50%, -50%)' }}
                onClick={() => handleInteraction('head')}
             >
                {/* Speech Bubble */}
                {currentThought && (
                  <div className="absolute -top-12 left-1/2 -translate-x-1/2 bg-white px-3 py-1 rounded-full text-xs font-bold text-amber-800 shadow-lg whitespace-nowrap animate-bounce">
                    {currentThought}
                    <div className="absolute bottom-0 left-1/2 -translate-x-1/2 translate-y-full w-0 h-0 border-l-[6px] border-l-transparent border-r-[6px] border-r-transparent border-t-[8px] border-t-white" />
                  </div>
                )}

                <img 
                  src={pet.pixelArt} 
                  className={`w-32 h-32 pixelated transition-transform hover:scale-110 nostalgic-glow rounded-xl
                    ${petAnimation === 'walking' ? 'animate-bounce' : 'animate-float'}
                    ${isNight ? 'brightness-75' : 'brightness-100'}
                  `}
                  alt={pet.name}
                />
             </div>
          </div>

          <GameUI 
            stats={stats} 
            currentMap={currentMap} 
            onNavigate={setCurrentMap}
            onFeed={handleFeed}
            onOpenJournal={() => setIsJournalOpen(true)}
            petName={pet.name}
          />
        </div>
      )}

      {/* Journal Modal */}
      {isJournalOpen && (
        <div className="fixed inset-0 z-50 bg-black/40 backdrop-blur-sm flex items-center justify-center p-6">
          <div className="bg-amber-50 w-full max-w-lg h-[80vh] rounded-3xl shadow-2xl overflow-hidden flex flex-col border-4 border-amber-200">
            <div className="p-6 bg-amber-400 text-white flex justify-between items-center">
              <div className="flex items-center gap-2">
                <BookOpen className="w-6 h-6" />
                <h3 className="text-xl font-bold">回忆日记</h3>
              </div>
              <button 
                onClick={() => setIsJournalOpen(false)}
                className="w-8 h-8 rounded-full bg-white/20 hover:bg-white/40 flex items-center justify-center font-bold"
              >
                ✕
              </button>
            </div>

            <div className="flex-1 overflow-y-auto p-6 space-y-6">
              {journal.map((entry, idx) => (
                <div key={idx} className="bg-white p-4 rounded-2xl shadow-sm border-l-4 border-amber-300">
                  <span className="text-xs font-bold text-amber-400 block mb-2">{entry.date}</span>
                  <p className="text-amber-900 italic leading-relaxed">"{entry.content}"</p>
                </div>
              ))}
              {journal.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center opacity-40 text-amber-900">
                  <BookOpen className="w-12 h-12 mb-2" />
                  <p>这里还没有写下回忆...</p>
                </div>
              )}
            </div>

            <div className="p-6 bg-amber-100/50 text-center">
              <p className="text-xs text-amber-700 font-medium">“每一次想念，都是跨越彩虹桥的拥抱。”</p>
            </div>
          </div>
        </div>
      )}

      {/* Night Filter Overlay */}
      {isNight && (
        <div className="fixed inset-0 pointer-events-none bg-indigo-900/10 mix-blend-multiply" />
      )}
    </div>
  );
};

export default App;

