import React, { useState, useEffect, useMemo } from 'react';
import { PetStats, PetInfo, MapType, JournalEntry, ExploreEvent } from './types';
import { INITIAL_STATS, COLORS } from './constants';
import { Pixelator } from './components/Pixelator';
import { GameUI } from './components/GameUI';
import { Pet3D } from './components/Pet3D';
import { generateJournalEntry } from './services/geminiService';
import { Moon, Sun, Sparkles, Wind, Info, BookOpen, Flame, Flower, MapPin } from 'lucide-react';

const App: React.FC = () => {
  const [pet, setPet] = useState<PetInfo | null>(null);
  const [stats, setStats] = useState<PetStats & { peace: number }>({ ...INITIAL_STATS, peace: 50 });
  const [currentMap, setCurrentMap] = useState<MapType>('HOME');
  const [isJournalOpen, setIsJournalOpen] = useState(false);
  const [journal, setJournal] = useState<JournalEntry[]>([]);
  const [isNight, setIsNight] = useState(false);
  const [petPosition, setPetPosition] = useState({ x: 50, y: 60 });
  const [petAnimation, setPetAnimation] = useState<'idle' | 'walking' | 'sleeping'>('idle');
  const [currentThought, setCurrentThought] = useState<string | null>(null);
  const [isPraying, setIsPraying] = useState(false);

  // Random Exploration Events
  const exploreEvents = useMemo(() => {
    return [
      { id: '1', x: 25, y: 45, type: 'mystery', icon: '✨' },
      { id: '2', x: 70, y: 35, type: 'memory', icon: '🏮' },
      { id: '3', x: 45, y: 75, type: 'gift', icon: '🎁' }
    ] as ExploreEvent[];
  }, []);

  useEffect(() => {
    const hour = new Date().getHours();
    setIsNight(hour < 6 || hour > 19);
    const interval = setInterval(() => {
      setStats(prev => ({
        ...prev,
        mood: Math.max(0, prev.mood - 0.5),
        hunger: Math.max(0, prev.hunger - 1),
        energy: isNight ? Math.min(100, prev.energy + 2) : Math.max(0, prev.energy - 0.5)
