import React, { useRef, useState } from 'react';

interface PixelatorProps {
  onComplete: (pixelData: string, hdData: string) => void;
}

export const Pixelator: React.FC<PixelatorProps> = ({ onComplete }) => {
  const [loading, setLoading] = useState(false);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const hdCanvasRef = useRef<HTMLCanvasElement>(null);

  const processImage = (file: File) => {
    setLoading(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const canvas = canvasRef.current;
        const hdCanvas = hdCanvasRef.current;
        if (!canvas || !hdCanvas) return;

        const ctx = canvas.getContext('2d');
        const hdCtx = hdCanvas.getContext('2d');
        if (!ctx || !hdCtx) return;

        // 1. Pixel version (32x32) - for the classic game feel
        canvas.width = 32;
        canvas.height = 32;
        ctx.imageSmoothingEnabled = false;
        ctx.drawImage(img, 0, 0, 32, 32);
        const pixelData = canvas.toDataURL('image/png');

        // 2. HD version (512x512) - for the 3D standee
        hdCanvas.width = 512;
        hdCanvas.height = 512;
        hdCtx.imageSmoothingEnabled = true;

        // Calculate aspect ratio crop
        const minSize = Math.min(img.width, img.height);
        const startX = (img.width - minSize) / 2;
        const startY = (img.height - minSize) / 2;

        // Create a rounded card mask for the HD image
        hdCtx.save();
        const radius = 60;
        hdCtx.beginPath();
        hdCtx.moveTo(radius, 0);
        hdCtx.lineTo(512 - radius, 0);
        hdCtx.quadraticCurveTo(512, 0, 512, radius);
        hdCtx.lineTo(512, 512 - radius);
        hdCtx.quadraticCurveTo(512, 512, 512 - radius, 512);
        hdCtx.lineTo(radius, 512);
        hdCtx.quadraticCurveTo(0, 512, 0, 512 - radius);
        hdCtx.lineTo(0, radius);
        hdCtx.quadraticCurveTo(0, 0, radius, 0);
        hdCtx.closePath();
        hdCtx.clip();

        hdCtx.drawImage(img, startX, startY, minSize, minSize, 0, 0, 512, 512);

        // Add a soft inner glow
        hdCtx.strokeStyle = 'rgba(255,255,255,0.3)';
        hdCtx.lineWidth = 10;
        hdCtx.stroke();
        hdCtx.restore();

        const hdData = hdCanvas.toDataURL('image/png');

        onComplete(pixelData, hdData);
        setLoading(false);
      };
      img.src = e.target?.result as string;
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="flex flex-col items-center justify-center p-10 bg-white/40 rounded-[3rem] border-4 border-dashed border-amber-200/50 backdrop-blur-sm">
      <canvas ref={canvasRef} className="hidden" />
      <canvas ref={hdCanvasRef} className="hidden" />

      <div className="w-20 h-20 bg-amber-100 rounded-full flex items-center justify-center mb-6 shadow-inner">
        <span className="text-4xl">📸</span>
      </div>

      <p className="mb-6 text-amber-900 text-center font-bold text-lg max-w-xs leading-relaxed">
        {loading ? "正在重构回忆..." : "上传照片，为你心爱的伙伴建立一个3D纪念空间"}
      </p>

      <input
        type="file"
        accept="image/*"
        onChange={(e) => e.target.files?.[0] && processImage(e.target.files[0])}
        className="hidden"
        id="pet-upload"
      />
      <label
        htmlFor="pet-upload"
        className="cursor-pointer bg-gradient-to-r from-amber-400 to-orange-400 hover:from-amber-500 hover:to-orange-500 text-white font-bold px-10 py-4 rounded-2xl shadow-xl transition-all active:scale-95 hover:shadow-orange-200/50"
      >
        即刻开始
      </label>

      <p className="mt-6 text-xs text-amber-600/60 font-medium">支持所有常用图片格式 • 自动高清处理</p>
    </div>
  );
};

