import { PetStats, PetInfo, MapType, JournalEntry, ExploreEvent } from './types';
import { INITIAL_STATS, COLORS } from './constants';
import { Pixelator } from './components/Pixelator';
import { GameUI } from './components/GameUI';
import { Pet3D } from './components/Pet3D';
import { generateJournalEntry } from './services/geminiService';
import { audio } from './services/audioService';
import { Moon, Sun, Sparkles, Wind, Info, BookOpen, Flame, Stars, Ghost, Volume2, VolumeX } from 'lucide-react';

const App: React.FC = () => {
  const [pet, setPet] = useState<PetInfo | null>(null);
  const [stats, setStats] = useState<PetStats & { peace: number }>({ ...INITIAL_STATS, peace: 50 });
  const [currentMap, setCurrentMap] = useState<MapType>('HOME');
  const [isJournalOpen, setIsJournalOpen] = useState(false);
  const [journal, setJournal] = useState<JournalEntry[]>([]);
  const [isNight, setIsNight] = useState(false);
  const [petPosition, setPetPosition] = useState({ x: 50, y: 60 });
  const [petAnimation, setPetAnimation] = useState<'idle' | 'walking' | 'sleeping'>('idle');
  const [currentThought, setCurrentThought] = useState<string | null>(null);
  const [isPraying, setIsPraying] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [is3DGenerating, setIs3DGenerating] = useState(false);

  // Random Exploration Events
  const exploreEvents = useMemo(() => {
    return [
      { id: '1', x: 30, y: 40, type: 'mystery', icon: '❓' },
      { id: '2', x: 65, y: 55, type: 'memory', icon: '💫' },
      { id: '3', x: 45, y: 70, type: 'gift', icon: '🦴' },
      { id: '4', x: 80, y: 45, type: 'mystery', icon: '🍃' }
    ] as ExploreEvent[];
  }, []);

  // Initialize Audio
  useEffect(() => {
    const handleFirstClick = () => {
      audio.init();
      audio.playEnvironment(currentMap, isNight);
      window.removeEventListener('click', handleFirstClick);
    };
    window.addEventListener('click', handleFirstClick);
    return () => window.removeEventListener('click', handleFirstClick);
  }, []);

  // Track map changes for audio
  useEffect(() => {
    if (!isMuted) {
      audio.playEnvironment(currentMap, isNight);
    }
  }, [currentMap, isNight, isMuted]);

  useEffect(() => {
    const checkTime = () => {
      const hour = new Date().getHours();
      setIsNight(hour < 6 || hour > 19);
    };
    checkTime();
    const timer = setInterval(checkTime, 60000);
    const statsInterval = setInterval(() => {
      setStats(prev => ({
        ...prev,
        mood: Math.max(0, prev.mood - 0.2),
        hunger: Math.max(0, prev.hunger - 0.5),
        energy: isNight ? Math.min(100, prev.energy + 1) : Math.max(0, prev.energy - 0.3)
      }));
    }, 15000);
    return () => { clearInterval(timer); clearInterval(statsInterval); };
  }, [isNight]);

  useEffect(() => {
    if (!pet || petAnimation === 'sleeping' || currentMap === 'SHRINE' || is3DGenerating) return;
    const moveInterval = setInterval(() => {
      if (Math.random() > 0.6) {
        setPetAnimation('walking');
        const nextX = Math.max(15, Math.min(85, petPosition.x + (Math.random() * 30 - 15)));
        const nextY = Math.max(35, Math.min(80, petPosition.y + (Math.random() * 15 - 7.5)));
        setPetPosition({ x: nextX, y: nextY });
        setTimeout(() => setPetAnimation('idle'), 3000);
      }
    }, 8000);
    return () => clearInterval(moveInterval);
  }, [pet, petPosition, petAnimation, currentMap, is3DGenerating]);

  const handlePetCreated = (pixelData: string, hdData: string) => {
    setIs3DGenerating(true);
    audio.playSFX('sparkle');

    // Simulate Image-to-3D AI Generation process
    setTimeout(() => {
      const name = prompt("给你的伙伴起个名字吧") || "我的宝贝";
      setPet({ name, type: 'cat', pixelArt: pixelData, hdArt: hdData });
      setJournal([{ date: new Date().toLocaleDateString(), content: `${name} 正在通过AI维度重塑，回到了这个充满爱的世界。` }]);
      setIs3DGenerating(false);
      audio.playSFX('pray');
    }, 3000);
  };

  const handlePray = async () => {
    if (!pet || isPraying) return;
    setIsPraying(true);
    audio.playSFX('pray');
    setStats(prev => ({ ...prev, peace: Math.min(100, prev.peace + 15), mood: Math.min(100, prev.mood + 10) }));

    setCurrentThought("听到了吗？这就是思念的回响...");
    const entryText = await generateJournalEntry(pet.name, stats, "在圣神龛前进行了每日祈祷，空灵的旋律洗涤了心灵。");
    setJournal(prev => [{ date: new Date().toLocaleDateString(), content: entryText, type: 'prayer' }, ...prev]);

    setTimeout(() => {
      setIsPraying(false);
      setCurrentThought(null);
    }, 6000);
  };

  const handleExploreEvent = async (event: ExploreEvent) => {
    if (!pet) return;
    audio.playSFX('sparkle');
    const reactions = {
      memory: "这个声音...是你以前经常玩耍的地方吗？",
      gift: "在林间拾起了一枚记忆的碎片。",
      mystery: "森林里回荡着治愈的音频，那是你在远方的叮咛。"
    };
    setCurrentThought(reactions[event.type]);
    const entryText = await generateJournalEntry(pet.name, stats, `在森林漫步中听到了回响 ${event.icon}。`);
    setJournal(prev => [{ date: new Date().toLocaleDateString(), content: entryText, type: 'discovery' }, ...prev]);
    setTimeout(() => setCurrentThought(null), 5000);
  };

  const theme = isNight ? COLORS.night : COLORS.day;

  return (
    <div className={`fixed inset-0 transition-colors duration-1000 ${theme.bg} overflow-hidden font-sans select-none`}>
      {/* Background Ambience */}
      <div className="absolute inset-0 opacity-40 pointer-events-none">
        {isNight ? (
          <div className="absolute top-20 left-1/4 w-96 h-96 bg-indigo-500/20 rounded-full blur-[120px] animate-pulse" />
        ) : (
          <div className="absolute -top-20 -right-20 w-[500px] h-[500px] bg-amber-200/30 rounded-full blur-[150px]" />
        )}
      </div>

      {!pet ? (
        <div className="flex flex-col items-center justify-center h-full px-6 text-center z-10 relative">
          <div className="mb-10 animate-float">
            <div className="bg-white/80 p-8 rounded-[3rem] shadow-2xl border-4 border-amber-100/50">
              <Sparkles className={`w-20 h-20 text-amber-500 ${is3DGenerating ? 'animate-spin' : ''}`} />
            </div>
          </div>
          <h1 className="text-4xl font-extrabold text-amber-950 mb-4 tracking-tight">彩虹桥：图生3D纪念馆</h1>
          <p className="text-amber-800/70 mb-12 max-w-sm text-lg font-medium leading-relaxed">
            {is3DGenerating ? "正在解析图像，通过深度神经网络重构伙伴的3D形态..." : "上传照片，让我们通过AI重构那份跨越生死的温存。"}
          </p>
          {!is3DGenerating && <Pixelator onComplete={handlePetCreated} />}
          {is3DGenerating && (
            <div className="w-64 h-2 bg-amber-100 rounded-full overflow-hidden shadow-inner">
              <div className="h-full bg-amber-400 animate-progress" style={{ width: '100%' }} />
            </div>
          )}
        </div>
      ) : (
        <div className="relative w-full h-full">
          {/* Top Control Bar */}
          <div className="absolute top-10 left-10 flex items-center gap-4 z-30">
             <div className="bg-white/50 backdrop-blur-md px-4 py-2 rounded-full border border-white/50 flex items-center gap-3 shadow-sm">
               {isNight ? <Moon className="w-5 h-5 text-indigo-400" /> : <Sun className="w-5 h-5 text-amber-500" />}
               <span className="font-bold text-xs tracking-widest text-amber-950">{new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
               <button 
                onClick={() => setIsMuted(!isMuted)} 
                className="hover:scale-110 transition-transform ml-2"
               >
                 {isMuted ? <VolumeX className="w-4 h-4 text-red-400" /> : <Volume2 className="w-4 h-4 text-emerald-500" />}
               </button>
             </div>
          </div>

          <div className="absolute top-10 right-10 text-right z-30">
            <div className="bg-white/50 backdrop-blur-md px-6 py-3 rounded-2xl border border-white/50 shadow-sm">
              <h2 className="text-2xl font-black text-amber-950 tracking-tight">{pet.name}</h2>
              <div className="flex items-center justify-end gap-2 mt-1">
                 <p className="text-[9px] font-black text-amber-700/60 uppercase tracking-widest">
                   {currentMap === 'HOME' ? 'At Peace' : currentMap === 'FOREST' ? 'Wandering' : 'Praying'}
                 </p>
              </div>
            </div>
          </div>

          {/* Rendering Layer */}
          <div className="relative w-full h-full">
             {/* Map: HOME */}
             {currentMap === 'HOME' && (
                <div className="absolute inset-0 flex items-center justify-center">
                   <div className="w-[90%] h-48 bg-amber-200/20 rounded-[50%] absolute bottom-[15%] blur-[100px]" />
                   <div className="absolute bottom-[30%] left-[10%] group">
                     <button 
                      onClick={() => { audio.playSFX('click'); setCurrentMap('SHRINE'); }}
                      className="flex flex-col items-center transition-all hover:scale-110"
                     >
                        <div className="relative w-24 h-32 flex items-center justify-center">
                          <div className="absolute inset-0 bg-white/40 backdrop-blur-lg rounded-t-full border-2 border-amber-100 shadow-xl" />
                          <Flame className={`w-10 h-10 z-10 ${isPraying ? 'text-orange-500 animate-pulse' : 'text-amber-200'}`} />
                        </div>
                        <span className="text-[10px] mt-3 font-black text-amber-900/40 uppercase tracking-widest">Peace Shrine</span>
