                   </div>
                   <div className="absolute bottom-[35%] right-[12%] w-32 h-44 bg-white rounded-xl shadow-2xl p-3 -rotate-2 border-8 border-amber-50 transition-all hover:rotate-0 hover:scale-110">
                      <div className="w-full h-full overflow-hidden rounded-sm bg-amber-50">
                        <img src={pet.hdArt || pet.pixelArt} className="w-full h-full object-cover opacity-90 grayscale-[0.2]" alt="Portrait" />
                      </div>
                      <div className="absolute -top-2 -left-2 w-6 h-6 bg-red-400 rounded-full border-4 border-white" />
                   </div>
                </div>
             )}

             {/* Map: SHRINE */}
             {currentMap === 'SHRINE' && (
               <div className="absolute inset-0 z-40 bg-amber-950/30 backdrop-blur-2xl flex items-center justify-center p-8 animate-in fade-in duration-700">
                  <div className="relative w-full max-w-sm bg-white/90 rounded-[4rem] border-8 border-white shadow-[0_60px_120px_rgba(0,0,0,0.3)] p-12 flex flex-col items-center">
                    <button 
                      onClick={() => { audio.playSFX('click'); setCurrentMap('HOME'); }}
                      className="absolute top-8 right-10 text-amber-950/20 hover:text-amber-950 transition-colors text-3xl font-black"
                    >✕</button>

                    <div className="w-48 h-48 rounded-full border-[10px] border-white shadow-2xl overflow-hidden mb-10 relative group">
                      <img src={pet.hdArt || pet.pixelArt} className="w-full h-full object-cover transition-transform duration-1000 group-hover:scale-125" alt="Shrine Pet" />
                      <div className={`absolute inset-0 bg-amber-400/20 transition-opacity duration-1000 ${isPraying ? 'opacity-100' : 'opacity-0'}`} />
                    </div>

                    <h3 className="text-3xl font-black text-amber-950 mb-4">思念之音</h3>
                    <p className="text-sm text-center text-amber-800/60 leading-relaxed mb-12 italic px-4">
                      “听，那是时光在流转，每一声旋律都是它在远方向你问候。”
                    </p>

                    <button 
                      onClick={handlePray}
                      disabled={isPraying}
                      className={`group relative overflow-hidden bg-gradient-to-r from-orange-400 to-amber-500 text-white font-black px-14 py-6 rounded-[2.5rem] shadow-2xl transition-all active:scale-95
                        ${isPraying ? 'animate-pulse' : 'hover:shadow-orange-300/50 hover:-translate-y-2'}
                      `}
                    >
                      <div className="flex items-center gap-3 relative z-10">
                        <Flame className={`w-6 h-6 ${isPraying ? 'animate-bounce' : ''}`} /> 
                        <span className="tracking-widest">开启祈祷仪式</span>
                      </div>
                      <div className="absolute inset-0 bg-white/20 translate-x-full group-hover:translate-x-0 transition-transform duration-700" />
                    </button>
                  </div>
               </div>
             )}

             {/* Map: FOREST */}
             {currentMap === 'FOREST' && (
                <div className="absolute inset-0 bg-emerald-950/5 transition-opacity duration-1000">
                   <div className="absolute bottom-1/3 w-full flex justify-around opacity-40">
                      {[...Array(6)].map((_, i) => <Wind key={i} className="w-10 h-10 text-emerald-400 animate-pulse" style={{ animationDelay: `${i*1.5}s` }} />)}
                   </div>
                   {exploreEvents.map(event => (
                     <button
                        key={event.id}
                        onClick={() => handleExploreEvent(event)}
                        className="absolute group transition-all hover:scale-150"
                        style={{ left: `${event.x}%`, top: `${event.y}%` }}
                     >
                        <div className="relative w-16 h-16 flex items-center justify-center">
                          <div className="absolute inset-0 bg-white/40 rounded-full blur-2xl group-hover:blur-3xl transition-all animate-pulse" />
                          <div className="bg-white/50 backdrop-blur-lg w-full h-full rounded-full border border-white/60 flex items-center justify-center text-3xl shadow-xl relative z-10">
                            {event.icon}
                          </div>
                          <div className="absolute inset-0 border-2 border-white/60 rounded-full animate-ping opacity-20" />
                        </div>
                     </button>
                   ))}
                </div>
             )}

             {/* The 3D Pet Standee */}
             {currentMap !== 'SHRINE' && (
                <div 
                  className="absolute transition-all duration-3000 ease-in-out z-20"
                  style={{ left: `${petPosition.x}%`, top: `${petPosition.y}%`, transform: 'translate(-50%, -50%)' }}
                >
                    {currentThought && (
                      <div className="absolute -top-28 left-1/2 -translate-x-1/2 bg-white/95 backdrop-blur-xl px-8 py-4 rounded-[2.5rem] text-sm font-black text-amber-950 shadow-[0_30px_60px_rgba(0,0,0,0.2)] whitespace-nowrap animate-in slide-in-from-bottom-6 fade-in duration-500 border-2 border-amber-50">
                        {currentThought}
                        <div className="absolute bottom-0 left-1/2 -translate-x-1/2 translate-y-full w-0 h-0 border-l-[12px] border-l-transparent border-r-[12px] border-r-transparent border-t-[14px] border-t-white/95" />
                      </div>
                    )}
                    <Pet3D 
                      pixelImage={pet.pixelArt} 
                      hdImage={pet.hdArt}
                      isNight={isNight} 
                      animation={petAnimation} 
                      onClick={() => {
                        audio.playSFX('click');
                        const quotes = ["一直在这里哦", "森林的声音真好听", "想起了我们一起散步的日子", "嘿嘿，再摸摸我就更开心啦"];
                        setCurrentThought(quotes[Math.floor(Math.random()*quotes.length)]);
                        setTimeout(() => setCurrentThought(null), 4000);
                      }}
                    />
                </div>
             )}
          </div>

          <GameUI 
            stats={stats} 
            currentMap={currentMap} 
            onNavigate={(map) => { audio.playSFX('click'); setCurrentMap(map); }}
            onFeed={(food) => {
              audio.playSFX('feed');
              setStats(prev => ({ ...prev, hunger: Math.min(100, prev.hunger + food.hungerBoost), mood: Math.min(100, prev.mood + 5) }));
              setCurrentThought(`*开心* 这个 ${food.name} 充满了回忆的味道！`);
              setTimeout(() => setCurrentThought(null), 4000);
            }}
            onOpenJournal={() => { audio.playSFX('click'); setIsJournalOpen(true); }}
            petName={pet.name}
          />
        </div>
      )}

      {/* Journal Modal */}
      {isJournalOpen && (
        <div className="fixed inset-0 z-50 bg-amber-950/50 backdrop-blur-2xl flex items-center justify-center p-6 animate-in fade-in duration-500">
          <div className="bg-amber-50/95 w-full max-w-xl h-[85vh] rounded-[4rem] shadow-[0_80px_160px_rgba(0,0,0,0.4)] overflow-hidden flex flex-col border-[10px] border-white relative">
            <div className="p-10 bg-gradient-to-r from-amber-400 to-orange-400 text-white flex justify-between items-center relative z-10 shadow-lg">
              <div className="flex items-center gap-4">
                <div className="bg-white/25 p-3 rounded-2xl">
                  <BookOpen className="w-10 h-10" />
                </div>
                <div>
                  <h3 className="text-3xl font-black tracking-tighter">时光回响</h3>
                  <p className="text-[10px] opacity-70 font-black uppercase tracking-[0.4em]">Memory Echoes</p>
                </div>
              </div>
              <button onClick={() => { audio.playSFX('click'); setIsJournalOpen(false); }} className="w-14 h-14 rounded-3xl bg-white/20 hover:bg-white/40 flex items-center justify-center font-black text-2xl transition-all active:scale-90">✕</button>
            </div>
            <div className="flex-1 overflow-y-auto p-12 space-y-10 scrollbar-hide">
              {journal.map((entry, idx) => (
                <div key={idx} className={`p-8 rounded-[3rem] shadow-md border-2 transition-all hover:-translate-y-2 ${
                  entry.type === 'prayer' ? 'bg-orange-100/40 border-orange-200' : 
                  entry.type === 'discovery' ? 'bg-emerald-100/40 border-emerald-200' : 
                  'bg-white/80 border-amber-50'
                }`}>
                  <div className="flex justify-between items-center mb-6">
                    <span className="text-[10px] font-black text-amber-900/30 uppercase tracking-[0.3em]">{entry.date}</span>
                    {entry.type && (
                      <span className={`text-[9px] px-4 py-1.5 rounded-full font-black uppercase tracking-[0.2em] shadow-sm ${
                        entry.type === 'prayer' ? 'bg-orange-200 text-orange-800' : 'bg-emerald-200 text-emerald-800'
                      }`}>
                        {entry.type}
                      </span>
                    )}
                  </div>
                  <p className="text-amber-950 italic leading-relaxed text-lg font-semibold">“{entry.content}”</p>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* Night Filter */}
      <div className={`fixed inset-0 pointer-events-none transition-all duration-2000 ${isNight ? 'bg-indigo-900/15 mix-blend-multiply opacity-100' : 'opacity-0'}`} />
    </div>
  );
};

export default App;

