class AudioManager {
  private ctx: AudioContext | null = null;
  private bgmNode: GainNode | null = null;
  private currentMap: string = '';
  private oscillators: OscillatorNode[] = [];
  private noiseNode: AudioBufferSourceNode | null = null;

  init() {
    if (!this.ctx) {
      this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
      this.bgmNode = this.ctx.createGain();
      this.bgmNode.connect(this.ctx.destination);
      this.bgmNode.gain.value = 0.15;
    }
  }

  private stopAll() {
    this.oscillators.forEach(osc => {
      try { osc.stop(); } catch(e) {}
    });
    this.oscillators = [];
    if (this.noiseNode) {
      try { this.noiseNode.stop(); } catch(e) {}
      this.noiseNode = null;
    }
  }

  playEnvironment(map: string, isNight: boolean) {
    if (!this.ctx || !this.bgmNode) return;
    if (this.currentMap === map) return;
    this.currentMap = map;
    this.stopAll();

    if (map === 'HOME') {
      this.createPad([261.63, 329.63, 392.00], 0.04); // C Major warm
    } else if (map === 'FOREST') {
      this.createWind(0.02);
      this.createPad([349.23, 440.00, 523.25], 0.03); // F Major airy
    } else if (map === 'BEACH') {
      this.createWaves();
      this.createPad([293.66, 369.99, 440.00], 0.03); // D Major bright
    } else if (map === 'PARK') {
      this.createBirdAmbience();
      this.createPad([329.63, 415.30, 493.88], 0.03); // E Major lively
    } else if (map === 'SHRINE') {
      // Taoist Transcendence: Pentatonic scales with bell-like synthesis
      this.createTaoistChant();
    }
  }

  private createPad(freqs: number[], vol: number) {
    if (!this.ctx || !this.bgmNode) return;
    freqs.forEach(f => {
      const osc = this.ctx!.createOscillator();
      const g = this.ctx!.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(f, this.ctx!.currentTime);
      g.gain.setValueAtTime(0, this.ctx!.currentTime);
      g.gain.linearRampToValueAtTime(vol, this.ctx!.currentTime + 3);
      osc.connect(g);
      g.connect(this.bgmNode!);
      osc.start();
      this.oscillators.push(osc);
    });
  }

  private createWaves() {
    if (!this.ctx || !this.bgmNode) return;
    const bufferSize = 2 * this.ctx.sampleRate;
    const noiseBuffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const output = noiseBuffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) output[i] = Math.random() * 2 - 1;

    const source = this.ctx.createBufferSource();
    source.buffer = noiseBuffer;
    source.loop = true;

    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';

    const lfo = this.ctx.createOscillator();
    lfo.frequency.setValueAtTime(0.1, this.ctx.currentTime); // Wave period
    const lfoGain = this.ctx.createGain();
    lfoGain.gain.setValueAtTime(400, this.ctx.currentTime);
    lfo.connect(lfoGain);
    lfoGain.connect(filter.frequency);
    lfo.start();

    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(0.05, this.ctx.currentTime);

    source.connect(filter);
    filter.connect(gain);
    gain.connect(this.bgmNode);
    source.start();
    this.noiseNode = source;
  }

  private createBirdAmbience() {
    if (!this.ctx || !this.bgmNode) return;
    const interval = setInterval(() => {
      if (this.currentMap !== 'PARK') { clearInterval(interval); return; }
      if (Math.random() > 0.7) this.playSFX('sparkle');
    }, 2000);
  }

  private createWind(vol: number) {
    if (!this.ctx || !this.bgmNode) return;
    const bufferSize = 2 * this.ctx.sampleRate;
    const noiseBuffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const output = noiseBuffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) output[i] = Math.random() * 2 - 1;

    const source = this.ctx.createBufferSource();
    source.buffer = noiseBuffer;
    source.loop = true;

    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(800, this.ctx.currentTime);

    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(vol, this.ctx.currentTime);

    source.connect(filter);
    filter.connect(gain);
    gain.connect(this.bgmNode);
    source.start();
    this.noiseNode = source;
  }

  private createTaoistChant() {
    if (!this.ctx || !this.bgmNode) return;
    // Deep Drone
    this.createPad([65.41, 98.00], 0.06); // Low C and G

    // Ethereal Pentatonic Bells (C, D, E, G, A)
    const scale = [523.25, 587.33, 659.25, 783.99, 880.00];
    const bellInterval = setInterval(() => {
      if (this.currentMap !== 'SHRINE' || !this.ctx) { clearInterval(bellInterval); return; }
      if (Math.random() > 0.4) {
        const freq = scale[Math.floor(Math.random() * scale.length)];
        const osc = this.ctx.createOscillator();
        const g = this.ctx.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(freq, this.ctx.currentTime);
        g.gain.setValueAtTime(0, this.ctx.currentTime);
        g.gain.linearRampToValueAtTime(0.08, this.ctx.currentTime + 0.1);
        g.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + 4);
        osc.connect(g);
        g.connect(this.bgmNode!);
        osc.start();
        osc.stop(this.ctx.currentTime + 4.5);
      }
    }, 1500);
  }

  playSFX(type: 'click' | 'feed' | 'pray' | 'sparkle' | 'cat' | 'dog' | 'bird') {
    if (!this.ctx) return;
    const now = this.ctx.currentTime;
    const osc = this.ctx.createOscillator();
    const g = this.ctx.createGain();

    if (type === 'cat') {
      osc.type = 'sine';
      osc.frequency.setValueAtTime(880, now);
      osc.frequency.exponentialRampToValueAtTime(1200, now + 0.1);
      osc.frequency.exponentialRampToValueAtTime(800, now + 0.3);
      g.gain.setValueAtTime(0.05, now);
      g.gain.linearRampToValueAtTime(0, now + 0.3);
    } else if (type === 'dog') {
      osc.type = 'square';
      osc.frequency.setValueAtTime(150, now);
      osc.frequency.exponentialRampToValueAtTime(300, now + 0.05);
      g.gain.setValueAtTime(0.05, now);
      g.gain.linearRampToValueAtTime(0, now + 0.1);
    } else if (type === 'bird') {
      osc.type = 'sine';
      osc.frequency.setValueAtTime(2000, now);
      osc.frequency.exponentialRampToValueAtTime(3000, now + 0.05);
      osc.frequency.exponentialRampToValueAtTime(2000, now + 0.1);
      g.gain.setValueAtTime(0.05, now);
      g.gain.linearRampToValueAtTime(0, now + 0.1);
    } else if (type === 'click') {
      osc.type = 'sine';
      osc.frequency.setValueAtTime(440, now);
      g.gain.setValueAtTime(0.1, now);
      g.gain.linearRampToValueAtTime(0, now + 0.05);
    } else if (type === 'feed') {
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(220, now);
      osc.frequency.exponentialRampToValueAtTime(440, now + 0.2);
      g.gain.setValueAtTime(0.1, now);
      g.gain.linearRampToValueAtTime(0, now + 0.2);
    } else if (type === 'pray') {
      osc.type = 'sine';
      osc.frequency.setValueAtTime(440, now);
      osc.frequency.exponentialRampToValueAtTime(880, now + 1);
      g.gain.setValueAtTime(0, now);
      g.gain.linearRampToValueAtTime(0.15, now + 0.5);
      g.gain.exponentialRampToValueAtTime(0.001, now + 2);
    } else if (type === 'sparkle') {
      osc.type = 'sine';
      osc.frequency.setValueAtTime(1500 + Math.random() * 500, now);
      g.gain.setValueAtTime(0.08, now);
      g.gain.linearRampToValueAtTime(0, now + 0.2);
    }

    osc.connect(g);
    g.connect(this.ctx.destination);
    osc.start();
    osc.stop(now + 2.5);
  }
}

