      audio.playEnvironment(currentMap, isNight, hasCustomMusic);
      window.removeEventListener('click', handleFirstClick);
    };
    window.addEventListener('click', handleFirstClick);
    return () => window.removeEventListener('click', handleFirstClick);
  }, [currentMap, isNight, hasCustomMusic]);

  useEffect(() => {
    audio.setMute(isMuted);
  }, [isMuted]);

  useEffect(() => {
    audio.playEnvironment(currentMap, isNight, hasCustomMusic);
  }, [currentMap, isNight, hasCustomMusic]);

  useEffect(() => {
    const checkTime = () => {
      const hour = new Date().getHours();
      setIsNight(hour < 6 || hour > 19);
    };
    checkTime();
    const timer = setInterval(checkTime, 60000);
    const statsInterval = setInterval(() => {
      setStats(prev => ({
        ...prev,
        mood: Math.max(0, prev.mood - 0.2),
        hunger: Math.max(0, prev.hunger - 0.4),
        energy: isNight ? Math.min(100, prev.energy + 1) : Math.max(0, prev.energy - 0.3)
      }));
    }, 15000);
    return () => { clearInterval(timer); clearInterval(statsInterval); };
  }, [isNight]);

  useEffect(() => {
    if (!pet || petAnimation === 'sleeping' || currentMap === 'SHRINE' || is3DGenerating) return;
    const moveInterval = setInterval(() => {
      if (Math.random() > 0.5) {
        setPetAnimation('walking');
        const nextX = Math.max(10, Math.min(90, petPosition.x + (Math.random() * 40 - 20)));
        const nextY = Math.max(30, Math.min(80, petPosition.y + (Math.random() * 20 - 10)));
        setPetPosition({ x: nextX, y: nextY });
        setTimeout(() => setPetAnimation('idle'), 3000);
      }
    }, 6000);
    return () => clearInterval(moveInterval);
  }, [pet, petPosition, petAnimation, currentMap, is3DGenerating]);

  const handlePetCreated = async (pixelData: string, hdData: string) => {
    setIs3DGenerating(true);
    audio.playSFX('sparkle');

    const identifiedType = await identifyPet(hdData);

    setTimeout(() => {
      const speciesName = identifiedType === 'cat' ? '小猫' : identifiedType === 'dog' ? '小狗' : identifiedType === 'bird' ? '小鸟' : '可爱的伙伴';
      const name = prompt(`识别出这可能是一只${speciesName}。请设置它的名称：`, "我的宝贝") || "我的宝贝";
      setPet({ name, type: identifiedType, pixelArt: pixelData, hdArt: hdData });
      setJournal([{ date: new Date().toLocaleDateString(), content: `${name} 已入驻这个充满光明的维度。` }]);
      setIs3DGenerating(false);
      audio.playSFX('pray');
    }, 2000);
  };

  const handleRename = () => {
    if (newName.trim()) {
      setPet(prev => prev ? { ...prev, name: newName.trim() } : null);
      setJournal(prev => [{ date: new Date().toLocaleDateString(), content: `改名为 ${newName.trim()}，新的记忆开始了。` }, ...prev]);
      setIsNamingOpen(false);
      setNewName('');
      audio.playSFX('sparkle');
    }
  };

  const handlePray = async () => {
    if (!pet || isPraying) return;
    setIsPraying(true);
    audio.playSFX('pray');
    setStats(prev => ({ ...prev, peace: Math.min(100, prev.peace + 25), mood: Math.min(100, prev.mood + 15) }));

    setCurrentThought("佛系的宁静...一切皆是缘。");
    const entryText = await generateJournalEntry(pet.name, stats, "在禅意十足的神龛前静心打坐，感受到万物生灵的连接。");
    setJournal(prev => [{ date: new Date().toLocaleDateString(), content: entryText, type: 'prayer' }, ...prev]);

    setTimeout(() => { setIsPraying(false); setCurrentThought(null); }, 6000);
  };

  const handleMusicUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      await audio.playCustomMusic(file);
      setHasCustomMusic(true);
      setCurrentThought("换上了你专属的治愈旋律...");
      setTimeout(() => setCurrentThought(null), 4000);
    }
  };

  const handlePetInteraction = () => {
    if (!pet) return;
    audio.playSFX(pet.type);
    const quotes = petDialogues[pet.type] || petDialogues.other;
    setCurrentThought(quotes[Math.floor(Math.random() * quotes.length)]);
    setTimeout(() => setCurrentThought(null), 4000);
  };

  const theme = useMemo(() => {
    if (currentMap === 'FOREST') return COLORS.forest;
    if (currentMap === 'BEACH') return COLORS.beach;
    if (currentMap === 'PARK') return COLORS.park;
    return isNight ? COLORS.night : COLORS.day;
  }, [currentMap, isNight]);

