            <Leaf key={i} className="absolute text-emerald-300 opacity-20 animate-fall" 
              style={{ left: `${Math.random() * 100}%`, top: `-10%`, animationDelay: `${Math.random() * 10}s`, animationDuration: `${6 + Math.random() * 6}s` }} 
            />
          ))}
