      )}
      {currentMap === 'BEACH' && (
        <div className="absolute inset-0 pointer-events-none overflow-hidden">
             <div className="absolute bottom-0 w-full h-40 bg-gradient-to-t from-white/20 to-transparent animate-wave" />
             {[...Array(5)].map((_, i) => (
               <Waves key={i} className="absolute text-cyan-200 opacity-30 animate-float"
                 style={{ left: `${10 + i * 20}%`, bottom: '20%', animationDelay: `${i * 0.5}s` }}
