                  </div>
               </div>
             )}

             {currentMap !== 'HOME' && currentMap !== 'SHRINE' && (
                <div className="absolute inset-0">
                   {currentExploreEvents.map(event => (
                     <button
                        key={event.id}
                        onClick={() => {
                          audio.playSFX('sparkle');
                          const mapQuotes: Record<string, string[]> = {
                            FOREST: ["落叶归根，你的灵魂在这片森林中安息", "清风微拂，是你在树梢对我微笑吗？", "森林里每一声虫鸣都在述说我们的过去"],
                            BEACH: ["大海包容一切，包括我对你无尽的思念", "潮起潮落，带不走你留下的脚印", "每一颗细沙都记得你奔跑的快乐"],
                            PARK: ["蝴蝶双飞，那是你派来陪伴我的天使吗？", "夕阳下的长椅，仿佛你还在那里等我", "这里的阳光，正如你生前那般温暖"]
                          };
                          const pool = mapQuotes[currentMap] || ["发现了一抹名为‘缘分’的余晖"];
                          setCurrentThought(pool[Math.floor(Math.random() * pool.length)]);
                          setTimeout(() => setCurrentThought(null), 5000);
                        }}
                        className="absolute group transition-transform hover:scale-125"
                        style={{ left: `${event.x}%`, top: `${event.y}%` }}
                     >
                        <div className="relative w-16 h-16 flex items-center justify-center bg-white/40 backdrop-blur-xl rounded-full border border-white/60 shadow-2xl animate-float">
                          <div className="absolute inset-0 border-4 border-white/40 rounded-full animate-ping opacity-20" />
                          {event.icon}
                        </div>
                     </button>
                   ))}
                </div>
             )}

             {currentMap !== 'SHRINE' && (
                <div 
                  className="absolute transition-all duration-3000 ease-in-out z-20"
                  style={{ left: `${petPosition.x}%`, top: `${petPosition.y}%`, transform: 'translate(-50%, -50%)' }}
                >
                    {currentThought && (
                      <div className="absolute -top-28 left-1/2 -translate-x-1/2 bg-white/95 backdrop-blur-2xl px-8 py-4 rounded-[2.5rem] text-sm font-black text-amber-950 shadow-2xl whitespace-nowrap animate-in slide-in-from-bottom-6 duration-500 border-2 border-amber-50 max-w-xs text-center">
                        {currentThought}
                        <div className="absolute bottom-0 left-1/2 -translate-x-1/2 translate-y-full w-0 h-0 border-l-[12px] border-l-transparent border-r-[12px] border-r-transparent border-t-[14px] border-t-white/95" />
                      </div>
                    )}
                    <Pet3D 
                      pixelImage={pet.pixelArt} 
                      hdImage={pet.hdArt}
                      isNight={isNight} 
                      animation={petAnimation} 
                      onClick={handlePetInteraction}
