                </div>
             )}
          </div>

          <GameUI 
            stats={stats} 
            currentMap={currentMap} 
            onNavigate={(map) => { audio.playSFX('click'); setCurrentMap(map); }}
            onFeed={(food) => {
              audio.playSFX('chew');
              setTimeout(() => audio.playSFX('chew'), 200);
              setTimeout(() => audio.playSFX('chew'), 400);
              setStats(prev => ({ ...prev, hunger: Math.min(100, prev.hunger + food.hungerBoost), mood: Math.min(100, prev.mood + 5) }));
              const feedQuotes: Record<PetType, string> = {
                cat: "喵呜~ 这种咀嚼感太棒了...",
                dog: "汪！喀嚓喀嚓！真的好香！",
                bird: "啾啾！这是最棒的馈赠！",
                other: "每一口都充满了爱的味道。"
              };
              setCurrentThought(feedQuotes[pet.type] || feedQuotes.other);
              setTimeout(() => setCurrentThought(null), 5000);
            }}
            onOpenJournal={() => { audio.playSFX('click'); setIsJournalOpen(true); }}
            petName={pet.name}
          />
        </div>
      )}

      {/* Rename Modal */}
      {isNamingOpen && (
        <div className="fixed inset-0 z-[100] bg-black/40 backdrop-blur-2xl flex items-center justify-center p-6">
          <div className="bg-white rounded-[3rem] p-10 w-full max-w-sm shadow-2xl border-8 border-amber-100/50">
            <h3 className="text-2xl font-black text-amber-950 mb-6 flex items-center gap-3">
              <Edit2 className="w-6 h-6 text-amber-500" /> 修改名称
            </h3>
            <input 
              type="text" 
              value={newName}
              onChange={(e) => setNewName(e.target.value)}
              placeholder="输入新的名称..."
              className="w-full bg-amber-50 border-4 border-amber-100 rounded-2xl px-6 py-4 text-xl font-bold text-amber-950 focus:outline-none focus:border-amber-300 mb-8"
