      {isJournalOpen && (
        <div className="fixed inset-0 z-50 bg-black/30 backdrop-blur-2xl flex items-center justify-center p-6">
          <div className="bg-amber-50/95 w-full max-w-xl h-[85vh] rounded-[4.5rem] shadow-2xl overflow-hidden flex flex-col border-[10px] border-white relative">
            <div className="p-12 bg-gradient-to-tr from-amber-400 to-orange-400 text-white flex justify-between items-center shadow-lg">
              <div className="flex items-center gap-5">
                <BookOpen className="w-12 h-12" />
                <div>
                  <h3 className="text-3xl font-black tracking-tight">时光回响</h3>
                  <p className="text-[11px] font-black uppercase tracking-[0.4em] opacity-70">Memory Scrolls</p>
                </div>
              </div>
              <button onClick={() => setIsJournalOpen(false)} className="w-14 h-14 rounded-3xl bg-white/20 flex items-center justify-center font-black">✕</button>
            </div>
            <div className="flex-1 overflow-y-auto p-12 space-y-12 scrollbar-hide">
              {journal.map((entry, idx) => (
                <div key={idx} className={`p-10 rounded-[3.5rem] border-2 transition-transform hover:-translate-y-2 ${entry.type === 'prayer' ? 'bg-orange-50/60 border-orange-200' : 'bg-white border-amber-50'}`}>
                  <span className="text-[10px] font-black text-amber-900/20 uppercase tracking-[0.3em] block mb-5">{entry.date}</span>
