export default App;

export type PetStats = {
  mood: number;
  hunger: number;
  energy: number;
  peace: number;
};

export type PetType = 'cat' | 'dog' | 'bird' | 'other';

export interface Toy {
  id: string;
  type: 'ball' | 'plushie' | 'bed';
