export default App;

class AudioManager {
  private ctx: AudioContext | null = null;
  private bgmNode: GainNode | null = null;
  private customMusicSource: AudioBufferSourceNode | null = null;
  private currentMap: string = '';
  private oscillators: OscillatorNode[] = [];
  private noiseNode: AudioBufferSourceNode | null = null;
  private isMuted: boolean = false;

  init() {
    if (!this.ctx) {
      this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
      this.bgmNode = this.ctx.createGain();
      this.bgmNode.connect(this.ctx.destination);
      this.bgmNode.gain.value = 0.12;
    }
  }

  setMute(mute: boolean) {
    this.isMuted = mute;
    if (this.bgmNode) {
      this.bgmNode.gain.value = mute ? 0 : 0.12;
    }
  }

  private stopAll() {
    this.oscillators.forEach(osc => {
      try { osc.stop(); } catch(e) {}
    });
    this.oscillators = [];
    if (this.noiseNode) {
      try { this.noiseNode.stop(); } catch(e) {}
      this.noiseNode = null;
    }
    if (this.customMusicSource) {
      try { this.customMusicSource.stop(); } catch(e) {}
      this.customMusicSource = null;
    }
  }

  async playCustomMusic(file: File) {
    if (!this.ctx || !this.bgmNode) return;
    this.stopAll();
    const arrayBuffer = await file.arrayBuffer();
    const audioBuffer = await this.ctx.decodeAudioData(arrayBuffer);

    this.customMusicSource = this.ctx.createBufferSource();
    this.customMusicSource.buffer = audioBuffer;
    this.customMusicSource.loop = true;
    this.customMusicSource.connect(this.bgmNode);
    this.customMusicSource.start();
  }

  playEnvironment(map: string, isNight: boolean, hasCustom: boolean = false) {
    if (!this.ctx || !this.bgmNode) return;
    if (this.currentMap === map && !hasCustom) return;
    this.currentMap = map;

    if (hasCustom) {
      this.oscillators.forEach(osc => { try { osc.stop(); } catch(e) {} });
      this.oscillators = [];
      if (this.noiseNode) { try { this.noiseNode.stop(); } catch(e) {} ; this.noiseNode = null; }
    } else {
      this.stopAll();
    }

    if (map === 'HOME') {
      if (!hasCustom) this.createSoftMelody([261.63, 329.63, 392.00, 523.25]); 
    } else if (map === 'FOREST') {
      this.createWind(0.015);
      if (!hasCustom) this.createSoftMelody([349.23, 440.00, 523.25, 698.46]); 
    } else if (map === 'BEACH') {
      this.createWaves();
      if (!hasCustom) this.createSoftMelody([293.66, 369.99, 440.00, 587.33]); 
    } else if (map === 'PARK') {
      this.createBirdAmbience();
      if (!hasCustom) this.createSoftMelody([329.63, 415.30, 493.88, 659.25]); 
    } else if (map === 'SHRINE') {
      if (!hasCustom) this.createSacredOrgan();
    }
  }

  private createSoftMelody(scale: number[]) {
    if (!this.ctx || !this.bgmNode) return;
    const interval = setInterval(() => {
      if (this.currentMap === 'SHRINE' || this.isMuted || !this.ctx || this.currentMap === '') {
        clearInterval(interval);
        return;
      }
      if (Math.random() > 0.65) {
        const freq = scale[Math.floor(Math.random() * scale.length)];
        const osc = this.ctx.createOscillator();
        const g = this.ctx.createGain();
        osc.type = 'sine';
        osc.frequency.setValueAtTime(freq, this.ctx.currentTime);
        g.gain.setValueAtTime(0, this.ctx.currentTime);
        g.gain.linearRampToValueAtTime(0.04, this.ctx.currentTime + 0.8);
        g.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + 4);
        osc.connect(g);
        g.connect(this.bgmNode!);
        osc.start();
        osc.stop(this.ctx.currentTime + 4.1);
      }
    }, 1800);
  }

  private createSacredOrgan() {
    if (!this.ctx || !this.bgmNode) return;
    const chords = [
      [261.63, 329.63, 392.00, 523.25], 
      [392.00, 493.88, 587.33, 783.99], 
      [349.23, 440.00, 523.25, 698.46], 
    ];
    let chordIdx = 0;
    const interval = setInterval(() => {
      if (this.currentMap !== 'SHRINE' || this.isMuted || !this.ctx) {
        clearInterval(interval);
        return;
      }
      const currentChord = chords[chordIdx];
      currentChord.forEach(f => {
        const osc1 = this.ctx!.createOscillator();
        const g = this.ctx!.createGain();
        osc1.type = 'sine';
        osc1.frequency.setValueAtTime(f, this.ctx!.currentTime);
        g.gain.setValueAtTime(0, this.ctx!.currentTime);
        g.gain.linearRampToValueAtTime(0.04, this.ctx!.currentTime + 1.5);
        g.gain.linearRampToValueAtTime(0, this.ctx!.currentTime + 5);
        osc1.connect(g);
        g.connect(this.bgmNode!);
        osc1.start();
        osc1.stop(this.ctx!.currentTime + 5.1);
      });
      chordIdx = (chordIdx + 1) % chords.length;
    }, 5000);
  }

  private createWaves() {
    if (!this.ctx || !this.bgmNode) return;
    const bufferSize = 2 * this.ctx.sampleRate;
    const noiseBuffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const output = noiseBuffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) output[i] = Math.random() * 2 - 1;
    const source = this.ctx.createBufferSource();
    source.buffer = noiseBuffer;
    source.loop = true;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    const lfo = this.ctx.createOscillator();
    lfo.frequency.setValueAtTime(0.12, this.ctx.currentTime);
    const lfoGain = this.ctx.createGain();
    lfoGain.gain.setValueAtTime(350, this.ctx.currentTime);
    lfo.connect(lfoGain);
    lfoGain.connect(filter.frequency);
    lfo.start();
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(0.04, this.ctx.currentTime);
    source.connect(filter);
    filter.connect(gain);
    gain.connect(this.bgmNode);
    source.start();
    this.noiseNode = source;
  }

  private createBirdAmbience() {
    if (!this.ctx || !this.bgmNode) return;
    const interval = setInterval(() => {
      if (this.currentMap !== 'PARK') { clearInterval(interval); return; }
      if (Math.random() > 0.75) this.playSFX('bird');
    }, 3000);
  }

  private createWind(vol: number) {
    if (!this.ctx || !this.bgmNode) return;
    const bufferSize = 2 * this.ctx.sampleRate;
    const noiseBuffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const output = noiseBuffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) output[i] = Math.random() * 2 - 1;
    const source = this.ctx.createBufferSource();
    source.buffer = noiseBuffer;
    source.loop = true;
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(600, this.ctx.currentTime);
    const gain = this.ctx.createGain();
    gain.gain.setValueAtTime(vol, this.ctx.currentTime);
    source.connect(filter);
    filter.connect(gain);
    gain.connect(this.bgmNode);
    source.start();
    this.noiseNode = source;
  }

  playSFX(type: 'click' | 'feed' | 'pray' | 'sparkle' | 'cat' | 'dog' | 'bird' | 'other' | 'chew') {
    if (!this.ctx || this.isMuted) return;
    const now = this.ctx.currentTime;
    const g = this.ctx.createGain();

    if (type === 'chew') {
      const bufferSize = 0.08 * this.ctx.sampleRate;
      const noiseBuffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
      const output = noiseBuffer.getChannelData(0);
      for (let i = 0; i < bufferSize; i++) output[i] = Math.random() * 2 - 1;
      const source = this.ctx.createBufferSource();
      source.buffer = noiseBuffer;
      const filter = this.ctx.createBiquadFilter();
      filter.type = 'bandpass';
      filter.frequency.setValueAtTime(1000 + Math.random() * 600, now);
      g.gain.setValueAtTime(0.15, now);
      g.gain.exponentialRampToValueAtTime(0.001, now + 0.06);
      source.connect(filter);
      filter.connect(g);
      source.start();
    } else if (type === 'cat') {
      const variant = Math.random();
      const osc = this.ctx.createOscillator();
      if (variant > 0.8) { // Deep Purr
        osc.frequency.setValueAtTime(150, now);
        osc.frequency.linearRampToValueAtTime(160, now + 0.15);
        g.gain.setValueAtTime(0.06, now);
      } else if (variant > 0.6) { // High Mew (Excited)
        osc.frequency.setValueAtTime(1400, now);
        osc.frequency.exponentialRampToValueAtTime(1100, now + 0.1);
        g.gain.setValueAtTime(0.07, now);
      } else if (variant > 0.4) { // Chirp
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(500, now);
        osc.frequency.exponentialRampToValueAtTime(800, now + 0.05);
        g.gain.setValueAtTime(0.05, now);
      } else if (variant > 0.2) { // Short Mew
        osc.frequency.setValueAtTime(900, now);
        osc.frequency.exponentialRampToValueAtTime(1000, now + 0.05);
        g.gain.setValueAtTime(0.06, now);
      } else { // Standard Meow
        osc.frequency.setValueAtTime(880, now);
        osc.frequency.exponentialRampToValueAtTime(1200, now + 0.1);
        osc.frequency.exponentialRampToValueAtTime(800, now + 0.3);
        g.gain.setValueAtTime(0.06, now);
      }
      osc.connect(g);
      osc.start();
      osc.stop(now + 0.4);
    } else if (type === 'dog') {
      const variant = Math.random();
      const osc = this.ctx.createOscillator();
      osc.type = 'triangle';
      if (variant > 0.8) { // Deep Woof
        osc.frequency.setValueAtTime(90, now);
        osc.frequency.exponentialRampToValueAtTime(220, now + 0.1);
        g.gain.setValueAtTime(0.1, now);
      } else if (variant > 0.6) { // Happy Yip
        osc.frequency.setValueAtTime(400, now);
        osc.frequency.exponentialRampToValueAtTime(700, now + 0.05);
        g.gain.setValueAtTime(0.08, now);
      } else if (variant > 0.4) { // Grumble
        osc.frequency.setValueAtTime(70, now);
        osc.frequency.linearRampToValueAtTime(90, now + 0.3);
        g.gain.setValueAtTime(0.05, now);
      } else if (variant > 0.2) { // Short Bark
        osc.frequency.setValueAtTime(250, now);
        osc.frequency.exponentialRampToValueAtTime(350, now + 0.05);
        g.gain.setValueAtTime(0.09, now);
      } else { // Standard Bark
        osc.frequency.setValueAtTime(190, now);
        osc.frequency.exponentialRampToValueAtTime(420, now + 0.04);
        g.gain.setValueAtTime(0.1, now);
      }
      osc.connect(g);
      osc.start();
      osc.stop(now + 0.3);
    } else if (type === 'bird') {
      const variant = Math.random();
      const osc = this.ctx.createOscillator();
      if (variant > 0.8) { // Fast Trill
        osc.frequency.setValueAtTime(3500, now);
        osc.frequency.setTargetAtTime(2500, now, 0.02);
        osc.frequency.setTargetAtTime(3500, now + 0.1, 0.02);
      } else if (variant > 0.6) { // High Whistle
        osc.type = 'sine';
        osc.frequency.setValueAtTime(2500, now);
        osc.frequency.linearRampToValueAtTime(4000, now + 0.2);
        g.gain.setValueAtTime(0.03, now);
      } else if (variant > 0.4) { // Triple Tweet
        osc.frequency.setValueAtTime(3000, now);
        osc.frequency.exponentialRampToValueAtTime(3500, now + 0.03);
        osc.frequency.exponentialRampToValueAtTime(3000, now + 0.06);
        osc.frequency.exponentialRampToValueAtTime(3500, now + 0.09);
      } else if (variant > 0.2) { // Soft Coo
        osc.type = 'sine';
        osc.frequency.setValueAtTime(400, now);
        osc.frequency.exponentialRampToValueAtTime(450, now + 0.2);
        g.gain.setValueAtTime(0.05, now);
      } else { // Standard Chirp
        osc.frequency.setValueAtTime(3200, now);
        osc.frequency.exponentialRampToValueAtTime(2000, now + 0.12);
      }
      g.gain.setValueAtTime(0.04, now);
      osc.connect(g);
      osc.start();
      osc.stop(now + 0.3);
    } else {
      const osc = this.ctx.createOscillator();
      if (type === 'click') {
        osc.frequency.setValueAtTime(440, now);
        g.gain.setValueAtTime(0.1, now);
      } else if (type === 'feed') {
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(220, now);
        osc.frequency.exponentialRampToValueAtTime(440, now + 0.2);
        g.gain.setValueAtTime(0.1, now);
      } else if (type === 'pray') {
        osc.type = 'sine';
        osc.frequency.setValueAtTime(523.25, now);
        osc.frequency.exponentialRampToValueAtTime(1046.50, now + 1.2);
        g.gain.setValueAtTime(0, now);
        g.gain.linearRampToValueAtTime(0.1, now + 0.4);
        g.gain.exponentialRampToValueAtTime(0.001, now + 2);
      } else {
        osc.frequency.setValueAtTime(1500, now);
        g.gain.setValueAtTime(0.05, now);
      }
      osc.connect(g);
      osc.start();
      osc.stop(now + 2);
    }

    g.connect(this.ctx.destination);
    g.gain.linearRampToValueAtTime(0, now + 2.5);
  }
}

