    }, 15000);
    return () => { clearInterval(timer); clearInterval(statsInterval); };
  }, [isNight]);

  useEffect(() => {
    if (pets.length === 0 || currentMap === 'SHRINE' || is3DGenerating) return;
    const moveInterval = setInterval(() => {
      setPetPositions(prev => prev.map((pos, i) => {
        if (Math.random() > 0.7) {
          return { x: Math.max(10, Math.min(90, pos.x + (Math.random() * 20 - 10))), y: Math.max(35, Math.min(80, pos.y + (Math.random() * 10 - 5))) };
        }
        return pos;
      }));
    }, 5000);
    return () => clearInterval(moveInterval);
  }, [pets, currentMap, is3DGenerating]);

  const handlePetCreated = async (pixelData: string, hdData: string) => {
    setIs3DGenerating(true);
    setIsUploadingNew(false);
    audio.playSFX('sparkle');
    const identifiedType = await identifyPet(hdData);

    setTimeout(() => {
      const speciesName = identifiedType === 'cat' ? '小猫' : identifiedType === 'dog' ? '小狗' : identifiedType === 'bird' ? '小鸟' : '可爱的伙伴';
      const name = prompt(`识别出是一只${speciesName}。请设置名称：`, "宝贝") || "宝贝";
      const newPet: PetInfo = { id: Math.random().toString(36).substr(2, 9), name, type: identifiedType, pixelArt: pixelData, hdArt: hdData, toys: [] };
      setPets(prev => [...prev, newPet]);
      setPetPositions(prev => [...prev, { x: 30 + Math.random() * 40, y: 50 + Math.random() * 20 }]);
      setPetAnimations(prev => [...prev, 'idle']);
      setJournal(prev => [{ date: new Date().toLocaleDateString(), content: `${name} 已加入彩虹桥家园。` }, ...prev]);
      setIs3DGenerating(false);
      audio.playSFX('pray');
    }, 1500);
  };

  const handleRename = () => {
    if (newName.trim() && currentPet) {
      setPets(prev => prev.map((p, i) => i === activePetIndex ? { ...p, name: newName.trim() } : p));
      setIsNamingOpen(false);
      audio.playSFX('sparkle');
    }
  };

  const addToy = (type: ToyType) => {
    if (!currentPet) return;
    const newToy: Toy = { id: Math.random().toString(36).substr(2, 9), type, x: 20 + Math.random() * 60, y: 45 + Math.random() * 25 };
    setPets(prev => prev.map((p, i) => i === activePetIndex ? { ...p, toys: [...(p.toys || []), newToy] } : p));
    audio.playSFX('click');
    setIsToyBoxOpen(false);
  };

  const removeToy = (id: string) => {
    setPets(prev => prev.map((p, i) => i === activePetIndex ? { ...p, toys: (p.toys || []).filter(t => t.id !== id) } : p));
    audio.playSFX('click');
  };

  const handlePray = async () => {
    if (!currentPet || isPraying) return;
    setIsPraying(true);
    audio.playSFX('pray');
    setStats(prev => ({ ...prev, peace: Math.min(100, prev.peace + 25) }));
    setCurrentThought("佛前的宁静，是我们跨越维度的连接。");
    setTimeout(() => { setIsPraying(false); setCurrentThought(null); }, 5000);
  };

  return (
    <div className={`fixed inset-0 transition-all duration-1000 ${theme.bg} overflow-hidden font-sans select-none`}>
      {currentMap === 'HOME' && <div className="absolute inset-0 rainbow-bg pointer-events-none z-0" />}
      {currentMap === 'HOME' && currentPet?.homeBackground && (
        <div className="absolute inset-0 z-0 overflow-hidden pointer-events-none opacity-20">
          <img src={currentPet.homeBackground} className="w-full h-full object-cover grayscale-[0.1]" alt="Home" />
        </div>
      )}

      {pets.length === 0 || isUploadingNew ? (
        <div className="flex flex-col items-center justify-center h-full px-6 text-center z-10 relative">
          <div className="mb-10 animate-float">
            <div className="bg-white/80 p-8 rounded-[3rem] shadow-2xl border-4 border-amber-100/50">
              <Sparkles className={`w-20 h-20 text-amber-500 ${is3DGenerating ? 'animate-spin' : ''}`} />
            </div>
          </div>
          <h1 className="text-4xl font-black text-amber-950 mb-4 tracking-tighter">彩虹桥：禅意港湾</h1>
          <p className="text-amber-800/70 mb-12 max-w-sm text-lg font-medium leading-relaxed">
            {is3DGenerating ? "正在唤醒那段温馨的回忆..." : "上传照片，在这道永恒的彩虹下，重建你们的温馨港湾。"}
          </p>
          {!is3DGenerating && <Pixelator onComplete={handlePetCreated} />}
          {pets.length > 0 && <button onClick={() => setIsUploadingNew(false)} className="mt-6 text-amber-900/50 font-bold underline">返回家园</button>}
        </div>
      ) : (
        <div className="relative w-full h-full">
          {/* HUD Layer */}
          <div className="absolute top-8 left-8 flex items-center gap-3 z-30">
             <div className="bg-white/40 backdrop-blur-md px-4 py-2 rounded-2xl border border-white/40 flex items-center gap-3 shadow-sm">
               {isNight ? <Moon className="w-5 h-5 text-indigo-400" /> : <Sun className="w-5 h-5 text-amber-500" />}
               <span className="font-black text-[10px] tracking-widest text-amber-950">{new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
               <button onClick={() => setIsMuted(!isMuted)} className="p-1">
                 {isMuted ? <VolumeX className="w-4 h-4 text-red-400" /> : <Volume2 className="w-4 h-4 text-emerald-500" />}
               </button>
             </div>
             {pets.length < 3 && (
               <button onClick={() => setIsUploadingNew(true)} className="bg-amber-100 p-2 rounded-xl text-amber-900 shadow-sm border border-white">
                 <PlusCircle className="w-5 h-5" />
               </button>
             )}
          </div>

          <div className="absolute top-8 right-8 flex flex-col items-end gap-2 z-30">
            {pets.map((p, i) => (
              <button key={p.id} onClick={() => { audio.playSFX('click'); setActivePetIndex(i); }} 
                className={`flex items-center gap-3 px-4 py-2 rounded-2xl transition-all border shadow-sm backdrop-blur-md
                  ${i === activePetIndex ? 'bg-amber-400 text-white border-white scale-105' : 'bg-white/40 text-amber-950 border-white/30'}`}
              >
                <div className="w-6 h-6 rounded-full overflow-hidden border border-white">
                  <img src={p.hdArt || p.pixelArt} className="w-full h-full object-cover" alt="" />
                </div>
                <span className="text-xs font-black">{p.name}</span>
                {i === activePetIndex && <Edit2 className="w-3 h-3 cursor-pointer" onClick={(e) => { e.stopPropagation(); setIsNamingOpen(true); setNewName(p.name); }} />}
              </button>
            ))}
          </div>

          {/* Main Map Content */}
          <div className="relative w-full h-full">
            {currentMap === 'HOME' && (
              <div className="absolute inset-0 flex items-center justify-center">
                 {/* Toy Management */}
                 <div className="absolute top-32 left-8 flex flex-col gap-4 z-30">
                   <button onClick={() => setIsToyBoxOpen(!isToyBoxOpen)} className="w-14 h-14 bg-white/70 backdrop-blur-xl rounded-2xl flex items-center justify-center text-amber-900 shadow-xl border-2 border-white hover:scale-110 active:scale-95 transition-all">
                      <Box className="w-6 h-6" />
                   </button>
                   <button onClick={() => homeBgInputRef.current?.click()} className="w-14 h-14 bg-white/70 backdrop-blur-xl rounded-2xl flex items-center justify-center text-amber-900 shadow-xl border-2 border-white hover:scale-110 active:scale-95 transition-all">
                      <Camera className="w-6 h-6" />
                   </button>
                   <input type="file" ref={homeBgInputRef} className="hidden" accept="image/*" onChange={(e) => {
                     const f = e.target.files?.[0];
                     if(f) {
                       const r = new FileReader();
                       r.onload = (ev) => setPets(prev => prev.map((p, i) => i === activePetIndex ? {...p, homeBackground: ev.target?.result as string} : p));
                       r.readAsDataURL(f);
                     }
                   }} />
                 </div>

                 {/* Display Toys for current pet */}
                 {(currentPet?.toys || []).map(toy => (
                   <div key={toy.id} className="absolute z-10 animate-float" style={{ left: `${toy.x}%`, top: `${toy.y}%` }}>
                      <div className="relative group hover:scale-125 transition-transform cursor-pointer">
                        <span className="text-4xl">{toyTypes.find(t => t.type === toy.type)?.icon}</span>
                        <button onClick={() => removeToy(toy.id)} className="absolute -top-4 -right-4 bg-red-400 text-white rounded-full w-6 h-6 text-[10px] opacity-0 group-hover:opacity-100 transition-opacity"><Trash2 className="w-3 h-3 m-auto"/></button>
                      </div>
                   </div>
                 ))}

                 <button onClick={() => setCurrentMap('SHRINE')} className="absolute bottom-[25%] left-[10%] group transition-all z-20">
                    <div className="relative w-28 h-40 flex flex-col items-center justify-center bg-white/60 backdrop-blur-xl rounded-t-full border-4 border-white shadow-3xl">
                      <Flower className="w-12 h-12 text-amber-400" />
                      <span className="text-[10px] font-black text-amber-900/40 uppercase tracking-widest mt-2">禅意神龛</span>
                    </div>
                 </button>

                 <div className="absolute bottom-[35%] right-[8%] w-40 h-52 bg-white rounded-3xl shadow-3xl p-4 -rotate-6 border-8 border-amber-50 transition-all hover:rotate-0 hover:scale-105 z-10">
                    <div className="w-full h-full overflow-hidden rounded-2xl">
                      <img src={currentPet?.hdArt || currentPet?.pixelArt} className="w-full h-full object-cover" alt="" />
                    </div>
                 </div>
              </div>
            )}

            {currentMap === 'SHRINE' && (
               <div className="absolute inset-0 z-40 bg-white/10 backdrop-blur-3xl flex items-center justify-center p-8 animate-in zoom-in duration-700">
                  <div className="relative w-full max-w-sm bg-white/95 rounded-[4.5rem] border-[12px] border-white shadow-2xl p-12 flex flex-col items-center">
                    <button onClick={() => setCurrentMap('HOME')} className="absolute top-10 right-14 text-amber-950/20 text-4xl font-black hover:text-amber-950">✕</button>
                    <div className="w-44 h-44 rounded-full border-8 border-white shadow-xl overflow-hidden mb-8">
                      <img src={currentPet?.hdArt || currentPet?.pixelArt} className="w-full h-full object-cover" alt="" />
                    </div>
                    <h3 className="text-3xl font-black text-amber-950 flex items-center gap-3 mb-6"><Flower className="w-8 h-8 text-amber-400" /> 禅修祈愿</h3>
                    <p className="text-[12px] text-center text-amber-900/40 italic mb-10 leading-relaxed font-medium">“在这份宁静中，时间仿佛静止，每一份想念都化作佛前的莲花。”</p>
                    <button onClick={handlePray} disabled={isPraying} className={`px-16 py-6 rounded-[2.5rem] bg-gradient-to-tr from-amber-400 to-orange-400 text-white font-black shadow-2xl transition-all ${isPraying ? 'animate-pulse grayscale' : 'hover:-translate-y-1'}`}>
                      {isPraying ? '冥想中...' : '开启心灵共鸣'}
                    </button>
                  </div>
               </div>
            )}

            {/* Pets Display */}
            {currentMap !== 'SHRINE' && pets.map((p, i) => (
              <div key={p.id} className="absolute transition-all duration-3000 ease-in-out z-20" 
                style={{ left: `${petPositions[i]?.x}%`, top: `${petPositions[i]?.y}%`, transform: 'translate(-50%, -50%)', opacity: i === activePetIndex ? 1 : 0.6 }}
                onClick={() => { audio.playSFX(p.type); setActivePetIndex(i); }}
              >
                {i === activePetIndex && currentThought && (
                  <div className="absolute -top-32 left-1/2 -translate-x-1/2 bg-white/95 backdrop-blur-3xl px-8 py-4 rounded-[2.5rem] text-sm font-black text-amber-950 shadow-2xl animate-in slide-in-from-bottom-8 duration-500 border-2 border-amber-50">
                    {currentThought}
                    <div className="absolute bottom-0 left-1/2 -translate-x-1/2 translate-y-full w-0 h-0 border-l-[15px] border-l-transparent border-r-[15px] border-r-transparent border-t-[18px] border-t-white/95" />
                  </div>
                )}
                <Pet3D pixelImage={p.pixelArt} hdImage={p.hdArt} isNight={isNight} animation={petAnimations[i]} />
              </div>
            ))}
          </div>

          <GameUI 
            stats={stats} currentMap={currentMap} onNavigate={m => { audio.playSFX('click'); setCurrentMap(m); }}
            onFeed={food => {
              audio.playSFX('chew');
              setTimeout(() => audio.playSFX('chew'), 150);
              setTimeout(() => audio.playSFX('chew'), 300);
              setStats(prev => ({ ...prev, hunger: Math.min(100, prev.hunger + food.hungerBoost), mood: Math.min(100, prev.mood + 5) }));
              const feedQuotes: Record<PetType, string> = { cat: "喵喵~ 这是最棒的奖励...", dog: "汪汪！太香了！", bird: "啾啾！这是充满回忆的美味...", other: "谢谢你一直记得我的喜好。" };
              setCurrentThought(feedQuotes[currentPet?.type || 'other']);
              setTimeout(() => setCurrentThought(null), 5000);
            }}
            onOpenJournal={() => { audio.playSFX('click'); setIsJournalOpen(true); }}
            petName={currentPet?.name || ''}
          />
        </div>
      )}

      {/* Modals */}
      {isToyBoxOpen && (
        <div className="fixed inset-0 z-[110] bg-black/20 backdrop-blur-md flex items-center justify-center p-6 animate-in zoom-in duration-300">
          <div className="bg-white/95 backdrop-blur-2xl rounded-[4rem] p-10 w-full max-w-sm shadow-3xl border-8 border-amber-100/50">
            <h3 className="text-2xl font-black text-amber-950 mb-8 flex items-center gap-3"><Box className="w-8 h-8 text-amber-500" /> 玩具箱</h3>
            <div className="grid grid-cols-3 gap-4">
              {toyTypes.map(t => (
                <button key={t.type} onClick={() => addToy(t.type)} className="aspect-square bg-amber-50/50 rounded-2xl flex flex-col items-center justify-center gap-1 hover:bg-amber-100 transition-all border border-amber-100/30">
                  <span className="text-3xl">{t.icon}</span>
                  <span className="text-[8px] font-bold text-amber-900/50">{t.label}</span>
                </button>
              ))}
            </div>
            <button onClick={() => setIsToyBoxOpen(false)} className="w-full mt-8 py-4 rounded-2xl font-black text-amber-900 bg-amber-100">关闭</button>
          </div>
        </div>
      )}

      {isNamingOpen && (
        <div className="fixed inset-0 z-[120] bg-black/40 backdrop-blur-2xl flex items-center justify-center p-6">
          <div className="bg-white rounded-[4rem] p-12 w-full max-w-sm shadow-3xl border-[10px] border-amber-100/50 text-center">
            <h3 className="text-2xl font-black text-amber-950 mb-8 flex items-center justify-center gap-3"><Edit2 className="w-6 h-6 text-amber-500" /> 修改名称</h3>
            <input type="text" value={newName} onChange={e => setNewName(e.target.value)} className="w-full bg-amber-50 border-4 border-amber-100 rounded-2xl px-6 py-4 text-xl font-black text-amber-950 text-center mb-10 focus:outline-none" autoFocus />
            <div className="flex gap-4">
              <button onClick={() => setIsNamingOpen(false)} className="flex-1 px-6 py-4 rounded-2xl font-black text-amber-900 bg-amber-100">取消</button>
              <button onClick={handleRename} className="flex-2 px-10 py-4 rounded-2xl font-black text-white bg-amber-500 shadow-xl">确认</button>
            </div>
          </div>
        </div>
      )}

      {isJournalOpen && (
        <div className="fixed inset-0 z-50 bg-black/30 backdrop-blur-3xl flex items-center justify-center p-6 animate-in fade-in duration-700">
          <div className="bg-amber-50/95 w-full max-w-xl h-[85vh] rounded-[5rem] shadow-3xl overflow-hidden flex flex-col border-[12px] border-white">
            <div className="p-12 bg-gradient-to-tr from-amber-400 to-orange-400 text-white flex justify-between items-center shadow-2xl relative z-10">
              <div className="flex items-center gap-6"><BookOpen className="w-14 h-14" /><div><h3 className="text-4xl font-black tracking-tighter">时光回响</h3><p className="text-[10px] font-black uppercase tracking-[0.4em] opacity-80">Memories of Our Bond</p></div></div>
              <button onClick={() => setIsJournalOpen(false)} className="w-14 h-14 rounded-3xl bg-white/20 flex items-center justify-center font-black text-3xl">✕</button>
            </div>
            <div className="flex-1 overflow-y-auto p-12 space-y-12 scrollbar-hide">
              {journal.map((e, idx) => (
                <div key={idx} className="p-10 rounded-[3.5rem] bg-white border-2 border-amber-50 shadow-sm transition-all hover:-translate-y-1">
                  <span className="text-[10px] font-black text-amber-900/30 uppercase tracking-[0.3em] block mb-4">{e.date}</span>
                  <p className="text-amber-950 italic leading-relaxed text-xl font-black">“{e.content}”</p>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { PetStats, PetInfo, MapType, JournalEntry, ExploreEvent, PetType, Toy, ToyType } from './types';
import { INITIAL_STATS, COLORS } from './constants';
import { Pixelator } from './components/Pixelator';
import { GameUI } from './components/GameUI';
import { Pet3D } from './components/Pet3D';
import { generateJournalEntry, identifyPet } from './services/geminiService';
import { audio } from './services/audioService';
import { Moon, Sun, Sparkles, Wind, Info, BookOpen, Stars, Ghost, Volume2, VolumeX, Waves, Ship, Music, Leaf, CloudRain, Shell, Umbrella, Bird, Dog, Cat, Camera, Flower, Edit2, Upload, Trash2, Box, PlusCircle } from 'lucide-react';

const App: React.FC = () => {
  const [pets, setPets] = useState<PetInfo[]>([]);
  const [activePetIndex, setActivePetIndex] = useState(0);
  const [stats, setStats] = useState<PetStats & { peace: number }>({ ...INITIAL_STATS, peace: 50 });
  const [currentMap, setCurrentMap] = useState<MapType>('HOME');
  const [isJournalOpen, setIsJournalOpen] = useState(false);
  const [isNamingOpen, setIsNamingOpen] = useState(false);
  const [isToyBoxOpen, setIsToyBoxOpen] = useState(false);
  const [isUploadingNew, setIsUploadingNew] = useState(false);
  const [newName, setNewName] = useState('');
  const [journal, setJournal] = useState<JournalEntry[]>([]);
  const [isNight, setIsNight] = useState(false);
  const [petPositions, setPetPositions] = useState<{x: number, y: number}[]>([]);
  const [petAnimations, setPetAnimations] = useState<('idle' | 'walking' | 'sleeping')[]>([]);
  const [currentThought, setCurrentThought] = useState<string | null>(null);
  const [isPraying, setIsPraying] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [is3DGenerating, setIs3DGenerating] = useState(false);
  const [hasCustomMusic, setHasCustomMusic] = useState(false);

  const musicInputRef = useRef<HTMLInputElement>(null);
  const homeBgInputRef = useRef<HTMLInputElement>(null);

  const currentPet = pets[activePetIndex] || null;

  // Fix: Calculate theme based on current map and time of day to resolve the missing 'theme' reference
  const theme = useMemo(() => {
    if (currentMap === 'HOME') return isNight ? COLORS.night : COLORS.day;
    if (currentMap === 'FOREST') return COLORS.forest;
    if (currentMap === 'BEACH') return COLORS.beach;
    if (currentMap === 'PARK') return COLORS.park;
    return COLORS.day;
  }, [currentMap, isNight]);

  const mapEvents: Record<MapType, ExploreEvent[]> = {
    HOME: [], SHRINE: [],
    FOREST: [{ id: 'f1', x: 20, y: 40, type: 'mystery', icon: '🌲' }, { id: 'f2', x: 70, y: 55, type: 'memory', icon: '🍃' }, { id: 'f3', x: 40, y: 75, type: 'gift', icon: '🍄' }],
    BEACH: [{ id: 'b1', x: 25, y: 50, type: 'mystery', icon: '🐚' }, { id: 'b2', x: 60, y: 65, type: 'memory', icon: '🌊' }, { id: 'b3', x: 85, y: 40, type: 'gift', icon: '🦀' }],
    PARK: [{ id: 'p1', x: 30, y: 45, type: 'mystery', icon: '🦋' }, { id: 'p2', x: 65, y: 70, type: 'memory', icon: '🪁' }, { id: 'p3', x: 15, y: 60, type: 'gift', icon: '🍦' }]
  };

  const toyTypes: {type: ToyType, icon: string, label: string}[] = [
    {type: 'ball', icon: '🧶', label: '毛线球'},
    {type: 'plushie', icon: '🧸', label: '小熊'},
    {type: 'bed', icon: '🛋️', label: '暖和垫子'},
    {type: 'tunnel', icon: '🚇', label: '猫隧道'},
    {type: 'scratcher', icon: '🪜', label: '磨爪架'},
    {type: 'frisbee', icon: '🥏', label: '飞盘'},
    {type: 'stick', icon: '🪄', label: '逗猫棒'},
    {type: 'mirror', icon: '🪞', label: '小镜子'},
    {type: 'fountain', icon: '⛲', label: '饮水机'}
  ];

  useEffect(() => {
    const handleFirstClick = () => { audio.init(); audio.playEnvironment(currentMap, isNight, hasCustomMusic); window.removeEventListener('click', handleFirstClick); };
    window.addEventListener('click', handleFirstClick);
    return () => window.removeEventListener('click', handleFirstClick);
  }, [currentMap, isNight, hasCustomMusic]);

  useEffect(() => { audio.setMute(isMuted); }, [isMuted]);
  useEffect(() => { audio.playEnvironment(currentMap, isNight, hasCustomMusic); }, [currentMap, isNight, hasCustomMusic]);

  useEffect(() => {
    const checkTime = () => { const hour = new Date().getHours(); setIsNight(hour < 6 || hour > 19); };
    checkTime();
    const timer = setInterval(checkTime, 60000);
    const statsInterval = setInterval(() => {
      setStats(prev => ({ ...prev, mood: Math.max(0, prev.mood - 0.2), hunger: Math.max(0, prev.hunger - 0.4), energy: isNight ? Math.min(100, prev.energy + 1) : Math.max(0, prev.energy - 0.3) }));
    }, 15000);
    return () => { clearInterval(timer); clearInterval(statsInterval); };
  }, [isNight]);

  useEffect(() => {
    if (pets.length === 0 || currentMap === 'SHRINE' || is3DGenerating) return;
    const moveInterval = setInterval(() => {
      setPetPositions(prev => prev.map((pos, i) => {
        if (Math.random() > 0.7) {
          return { x: Math.max(10, Math.min(90, pos.x + (Math.random() * 20 - 10))), y: Math.max(35, Math.min(80, pos.y + (Math.random() * 10 - 5))) };
        }
        return pos;
      }));
    }, 5000);
    return () => clearInterval(moveInterval);
  }, [pets, currentMap, is3DGenerating]);

  const handlePetCreated = async (pixelData: string, hdData: string) => {
    setIs3DGenerating(true);
    setIsUploadingNew(false);
    audio.playSFX('sparkle');
    const identifiedType = await identifyPet(hdData);

    setTimeout(() => {
      const speciesName = identifiedType === 'cat' ? '小猫' : identifiedType === 'dog' ? '小狗' : identifiedType === 'bird' ? '小鸟' : '可爱的伙伴';
      const name = prompt(`识别出是一只${speciesName}。请设置名称：`, "宝贝") || "宝贝";
      const newPet: PetInfo = { id: Math.random().toString(36).substr(2, 9), name, type: identifiedType, pixelArt: pixelData, hdArt: hdData, toys: [] };
      setPets(prev => [...prev, newPet]);
      setPetPositions(prev => [...prev, { x: 30 + Math.random() * 40, y: 50 + Math.random() * 20 }]);
      setPetAnimations(prev => [...prev, 'idle']);
