        </div>
      )}

      {/* Modals */}
      {isToyBoxOpen && (
        <div className="fixed inset-0 z-[110] bg-black/20 backdrop-blur-md flex items-center justify-center p-6 animate-in zoom-in duration-300">
          <div className="bg-white/95 backdrop-blur-2xl rounded-[4rem] p-10 w-full max-w-sm shadow-3xl border-8 border-amber-100/50">
            <h3 className="text-2xl font-black text-amber-950 mb-8 flex items-center gap-3"><Box className="w-8 h-8 text-amber-500" /> 玩具箱</h3>
            <div className="grid grid-cols-3 gap-4">
              {toyTypes.map(t => (
                <button key={t.type} onClick={() => addToy(t.type)} className="aspect-square bg-amber-50/50 rounded-2xl flex flex-col items-center justify-center gap-1 hover:bg-amber-100 transition-all border border-amber-100/30">
