              ))}
            </div>
            <button onClick={() => setIsToyBoxOpen(false)} className="w-full mt-8 py-4 rounded-2xl font-black text-amber-900 bg-amber-100">关闭</button>
          </div>
        </div>
      )}

      {isNamingOpen && (
        <div className="fixed inset-0 z-[120] bg-black/40 backdrop-blur-2xl flex items-center justify-center p-6">
          <div className="bg-white rounded-[4rem] p-12 w-full max-w-sm shadow-3xl border-[10px] border-amber-100/50 text-center">
            <h3 className="text-2xl font-black text-amber-950 mb-8 flex items-center justify-center gap-3"><Edit2 className="w-6 h-6 text-amber-500" /> 修改名称</h3>
            <input type="text" value={newName} onChange={e => setNewName(e.target.value)} className="w-full bg-amber-50 border-4 border-amber-100 rounded-2xl px-6 py-4 text-xl font-black text-amber-950 text-center mb-10 focus:outline-none" autoFocus />
            <div className="flex gap-4">
              <button onClick={() => setIsNamingOpen(false)} className="flex-1 px-6 py-4 rounded-2xl font-black text-amber-900 bg-amber-100">取消</button>
              <button onClick={handleRename} className="flex-2 px-10 py-4 rounded-2xl font-black text-white bg-amber-500 shadow-xl">确认</button>
            </div>
