                    <div className="absolute bottom-0 left-1/2 -translate-x-1/2 translate-y-full w-0 h-0 border-l-[15px] border-l-transparent border-r-[15px] border-r-transparent border-t-[18px] border-t-white/95" />
                  </div>
                )}
                <Pet3D pixelImage={p.pixelArt} hdImage={p.hdArt} isNight={isNight} animation={i === activePetIndex ? 'walking' : 'idle'} />
              </div>
            ))}
          </div>

          <GameUI 
            stats={stats} currentMap={currentMap} onNavigate={m => { audio.playSFX('click'); setCurrentMap(m); }}
