              audio.playSFX('chew');
              setTimeout(() => audio.playSFX('chew'), 180);
              setTimeout(() => audio.playSFX('chew'), 360);
              setStats(prev => ({ ...prev, hunger: Math.min(100, prev.hunger + food.hungerBoost), mood: Math.min(100, prev.mood + 5) }));
              handlePetInteract(activePetIndex); // Refresh quotes on feed
            }}
            onOpenJournal={() => { audio.playSFX('click'); setIsJournalOpen(true); }}
            petName={currentPet?.name || ''}
          />
        </div>
      )}

      {/* Toy Box Modal */}
      {isToyBoxOpen && (
        <div className="fixed inset-0 z-[110] bg-black/20 backdrop-blur-md flex items-center justify-center p-6 animate-in zoom-in duration-500">
