            <h3 className="text-3xl font-black text-amber-950 mb-10 flex items-center gap-4"><Box className="w-10 h-10 text-amber-500" /> 温馨玩具箱</h3>
            <div className="grid grid-cols-3 gap-5">
              {toyTypes.map(t => (
                <button key={t.type} onClick={() => addToy(t.type)} className="aspect-square bg-amber-50/50 rounded-3xl flex flex-col items-center justify-center gap-2 hover:bg-amber-100 transition-all border-2 border-amber-100/20 group">
                  <span className="text-4xl group-hover:scale-110 transition-transform">{t.icon}</span>
                  <span className="text-[9px] font-black text-amber-900/40 uppercase tracking-tighter">{t.label}</span>
                </button>
              ))}
            </div>
            <button onClick={() => setIsToyBoxOpen(false)} className="w-full mt-12 py-5 rounded-2xl font-black text-amber-900 bg-amber-100 hover:bg-amber-200 transition-colors">关闭玩具箱</button>
          </div>
        </div>
      )}

      {isNamingOpen && (
        <div className="fixed inset-0 z-[120] bg-black/40 backdrop-blur-2xl flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="bg-white rounded-[4rem] p-12 w-full max-w-sm shadow-3xl border-[12px] border-amber-100/50 text-center">
            <h3 className="text-2xl font-black text-amber-950 mb-10 flex items-center justify-center gap-4"><Edit2 className="w-8 h-8 text-amber-500" /> 修改名称</h3>
            <input type="text" value={newName} onChange={e => setNewName(e.target.value)} className="w-full bg-amber-50/50 border-4 border-amber-100 rounded-2xl px-8 py-5 text-2xl font-black text-amber-950 text-center mb-12 focus:outline-none focus:border-amber-300 transition-all" autoFocus />
            <div className="flex gap-4">
              <button onClick={() => setIsNamingOpen(false)} className="flex-1 px-8 py-5 rounded-2xl font-black text-amber-900 bg-amber-100 hover:bg-amber-200 transition-colors">取消</button>
              <button onClick={handleRename} className="flex-2 px-10 py-5 rounded-2xl font-black text-white bg-amber-500 hover:bg-amber-600 shadow-xl transition-all">确认修改</button>
            </div>
          </div>
        </div>
      )}

      {isJournalOpen && (
        <div className="fixed inset-0 z-50 bg-black/30 backdrop-blur-3xl flex items-center justify-center p-6 animate-in fade-in duration-1000">
          <div className="bg-amber-50/95 w-full max-w-xl h-[85vh] rounded-[5rem] shadow-3xl overflow-hidden flex flex-col border-[14px] border-white">
            <div className="p-14 bg-gradient-to-tr from-amber-400 to-orange-400 text-white flex justify-between items-center shadow-2xl relative z-10">
              <div className="flex items-center gap-6"><BookOpen className="w-16 h-16" /><div><h3 className="text-4xl font-black tracking-tighter">时光回响</h3><p className="text-[12px] font-black uppercase tracking-[0.5em] opacity-80">Eternal Memories</p></div></div>
              <button onClick={() => setIsJournalOpen(false)} className="w-16 h-16 rounded-[2rem] bg-white/20 flex items-center justify-center font-black text-3xl hover:bg-white/30 transition-all active:scale-90">✕</button>
            </div>
            <div className="flex-1 overflow-y-auto p-14 space-y-14 scrollbar-hide bg-amber-50/30">
              {journal.map((e, idx) => (
                <div key={idx} className="p-12 rounded-[4rem] bg-white border-4 border-amber-50 shadow-sm transition-all hover:-translate-y-2 hover:shadow-xl">
                  <span className="text-[11px] font-black text-amber-900/30 uppercase tracking-[0.4em] block mb-6">{e.date}</span>
                  <p className="text-amber-950 italic leading-relaxed text-xl font-black">“{e.content}”</p>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
