      {/* The Volumetric Standee */}
      <div 
        className={`relative transition-all duration-1000 ease-out preserve-3d
          ${animation === 'walking' ? 'animate-bounce' : animation === 'sleeping' ? 'opacity-80 scale-90 translate-y-4' : 'animate-float'}
