            ${!hdImage ? 'pixelated' : ''}
            shadow-[0_30px_60px_rgba(0,0,0,0.25)]
            border-[6px] border-white/40 backdrop-blur-[4px]
          `}
          style={{ transform: 'translateZ(25px)' }}
        >
          <img 
            src={displayImage} 
            className="w-full h-full object-cover scale-110"
            alt="Pet"
          />
          {/* Surface Shine */}
          <div className="absolute inset-0 bg-gradient-to-tr from-transparent via-white/15 to-transparent -translate-x-full group-hover:translate-x-full transition-transform duration-1000" />
        </div>

        {/* Mid-Depth Layer (The "Core") */}
        <div 
          className="absolute inset-0 w-44 h-44 rounded-3xl bg-white/20 border-2 border-white/30 backdrop-blur-md"
          style={{ transform: 'translateZ(12px)' }}
        />

        {/* Back Depth Layer (The "Frame") */}
        <div 
          className="absolute inset-0 w-44 h-44 rounded-3xl bg-amber-900/10 border-[3px] border-amber-900/5"
          style={{ transform: 'translateZ(2px)' }}
        />

        {/* Ambient Glow for 3D generation effect */}
        <div className="absolute inset-0 w-44 h-44 rounded-3xl opacity-0 group-hover:opacity-40 blur-2xl bg-amber-400 transition-opacity" style={{ transform: 'translateZ(0px)' }} />

        {/* Happy Sparkles */}
        <div className="absolute -top-6 -right-6 pointer-events-none opacity-0 group-hover:opacity-100 transition-opacity duration-500">
           <span className="text-2xl animate-ping block">✨</span>
           <span className="text-lg animate-bounce delay-100 block">⭐</span>
        </div>
      </div>
    </div>
  );
};

