  useEffect(() => {
    if (pets.length === 0 || currentMap === 'SHRINE' || is3DGenerating) return;

    const intervals = pets.map((pet) => {
      return setInterval(() => {
        if (Math.random() > 0.8) {
          audio.playSFX(pet.type);
          const lib = PET_LIBRARIES[pet.type];
          let pool = lib.calm;
          if (stats.hunger < 30) pool = lib.hunger;
          else if (stats.mood > 80) pool = lib.happy;
          else if (stats.energy < 30) pool = lib.energy;

          const quote = pool[Math.floor(Math.random() * pool.length)];
          setPetThoughts(prev => ({ ...prev, [pet.id]: quote }));
          setTimeout(() => {
            setPetThoughts(prev => ({ ...prev, [pet.id]: null }));
          }, 4000);
        }
      }, 5000 + Math.random() * 5000);
    });

    return () => intervals.forEach(clearInterval);
  }, [pets, stats, currentMap, is3DGenerating]);

  // Independent movement logic
  useEffect(() => {
    if (pets.length === 0 || currentMap === 'SHRINE' || is3DGenerating) return;
    const moveInterval = setInterval(() => {
      setPetPositions(prev => prev.map((pos) => {
        if (Math.random() > 0.6) {
          return { 
            x: Math.max(15, Math.min(85, pos.x + (Math.random() * 20 - 10))), 
            y: Math.max(40, Math.min(75, pos.y + (Math.random() * 10 - 5))) 
          };
        }
        return pos;
      }));
    }, 4000);
    return () => clearInterval(moveInterval);
  }, [pets, currentMap, is3DGenerating]);

  useEffect(() => {
    const handleFirstClick = () => { audio.init(); audio.playEnvironment(currentMap, isNight, hasCustomMusic); window.removeEventListener('click', handleFirstClick); };
    window.addEventListener('click', handleFirstClick);
    return () => window.removeEventListener('click', handleFirstClick);
  }, [currentMap, isNight, hasCustomMusic]);

  useEffect(() => { audio.setMute(isMuted); }, [isMuted]);
  useEffect(() => { audio.playEnvironment(currentMap, isNight, hasCustomMusic); }, [currentMap, isNight, hasCustomMusic]);

  useEffect(() => {
    const checkTime = () => { const hour = new Date().getHours(); setIsNight(hour < 6 || hour > 19); };
    checkTime();
    const timer = setInterval(checkTime, 60000);
    const statsInterval = setInterval(() => {
      setStats(prev => ({ ...prev, mood: Math.max(0, prev.mood - 0.1), hunger: Math.max(0, prev.hunger - 0.2), energy: isNight ? Math.min(100, prev.energy + 1) : Math.max(0, prev.energy - 0.1) }));
    }, 20000);
    return () => { clearInterval(timer); clearInterval(statsInterval); };
  }, [isNight]);

  const handlePetCreated = async (pixelData: string, hdData: string) => {
    setIs3DGenerating(true);
    setIsUploadingNew(false);
    audio.playSFX('sparkle');
    const identifiedType = await identifyPet(hdData);

    setTimeout(() => {
      const speciesName = identifiedType === 'cat' ? '小猫' : identifiedType === 'dog' ? '小狗' : identifiedType === 'bird' ? '小鸟' : '可爱的伙伴';
      const name = prompt(`识别出这是一只${speciesName}。请设置它的名称：`, "宝贝") || "宝贝";
      const id = Math.random().toString(36).substr(2, 9);
      const newPet: PetInfo = { id, name, type: identifiedType, pixelArt: pixelData, hdArt: hdData, toys: [] };
      setPets(prev => [...prev, newPet]);
      setPetPositions(prev => [...prev, { x: 30 + Math.random() * 40, y: 50 + Math.random() * 20 }]);
      setJournal(prev => [{ date: new Date().toLocaleDateString(), content: `${name} 加入了我们的世界。` }, ...prev]);
      setIs3DGenerating(false);
      audio.playSFX('pray');
    }, 1500);
  };

  const handleRename = () => {
    if (newName.trim() && currentPet) {
      setPets(prev => prev.map((p, i) => i === activePetIndex ? { ...p, name: newName.trim() } : p));
      setIsNamingOpen(false);
      audio.playSFX('sparkle');
    }
  };

  const handleEventClick = async (event: ExploreEvent) => {
    if (!currentPet) return;
    audio.playSFX('click');

    let message = "";
    if (currentMap === 'FOREST') {
      if (event.icon === '🍄') message = `${currentPet.name} 发现了一株发光的蘑菇，心灵得到了平静。`;
      if (event.icon === '🍂') message = `${currentPet.name} 在落叶堆里发现了一片记录着温柔时光的叶子。`;
      setStats(prev => ({ ...prev, peace: Math.min(100, prev.peace + 10) }));
    } else if (currentMap === 'BEACH') {
      if (event.icon === '🐚') message = `${currentPet.name} 捡起一个海螺，听到了大海的回响。`;
      if (event.icon === '🍾') message = `${currentPet.name} 发现了一个漂流瓶，里面写着“永远爱你”。`;
      setStats(prev => ({ ...prev, mood: Math.min(100, prev.mood + 10) }));
    } else if (currentMap === 'PARK') {
      if (event.icon === '🦋') message = `${currentPet.name} 正在欢快地追逐一只五彩斑斓的蝴蝶。`;
      if (event.icon === '🪁') message = `${currentPet.name} 看着天空中的风筝，眼神里充满了好奇。`;
      setStats(prev => ({ ...prev, energy: Math.min(100, prev.energy + 10) }));
    }

    const journalEntry = await generateJournalEntry(currentPet.name, stats, message || "在野外探索");
    setJournal(prev => [{ date: new Date().toLocaleDateString(), content: journalEntry }, ...prev]);

    setPetThoughts(prev => ({ ...prev, [currentPet.id]: message ? "看，我发现了好东西！" : "这里真有趣~" }));
    setTimeout(() => setPetThoughts(prev => ({ ...prev, [currentPet.id]: null })), 4000);

    // Temporarily remove the event
    setMapEvents(prev => ({
      ...prev,
      [currentMap]: prev[currentMap].filter(e => e.id !== event.id)
    }));

    // Respawn later
    setTimeout(() => {
      setMapEvents(prev => ({
        ...prev,
        [currentMap]: [...prev[currentMap], event]
      }));
    }, 30000);
  };

  const addToy = (type: ToyType) => {
    if (!currentPet) return;
    const newToy: Toy = { id: Math.random().toString(36).substr(2, 9), type, x: 20 + Math.random() * 60, y: 45 + Math.random() * 25 };
    setPets(prev => prev.map((p, i) => i === activePetIndex ? { ...p, toys: [...(p.toys || []), newToy] } : p));
    audio.playSFX('click');
    setIsToyBoxOpen(false);
  };

  const removeToy = (id: string) => {
    setPets(prev => prev.map((p, i) => i === activePetIndex ? { ...p, toys: (p.toys || []).filter(t => t.id !== id) } : p));
    audio.playSFX('click');
  };

  const handlePetInteract = (index: number) => {
    const pet = pets[index];
    if (!pet) return;
    setActivePetIndex(index);
    audio.playSFX(pet.type);
    const lib = PET_LIBRARIES[pet.type];
    const pool = stats.mood > 70 ? lib.happy : lib.calm;
    const quote = pool[Math.floor(Math.random() * pool.length)];
    setPetThoughts(prev => ({ ...prev, [pet.id]: quote }));
    setTimeout(() => {
      setPetThoughts(prev => ({ ...prev, [pet.id]: null }));
    }, 4000);
  };

  return (
    <div className={`fixed inset-0 transition-all duration-1000 ${theme.bg} overflow-hidden font-sans select-none`}>
      {/* Dynamic Background Overlays */}
      {currentMap === 'HOME' && <div className="absolute inset-0 rainbow-bg pointer-events-none z-0" />}
      {currentMap === 'FOREST' && (
        <div className="absolute inset-0 pointer-events-none z-0">
          {particles.map(p => (
            <div key={p.id} className="absolute text-orange-200/40 animate-fall" 
                 style={{ left: `${p.left}%`, animationDuration: `${p.duration}s`, animationDelay: `${p.delay}s`, fontSize: `${p.size}px` }}>🍃</div>
          ))}
        </div>
      )}
      {currentMap === 'BEACH' && (
        <div className="absolute bottom-0 w-full h-1/4 bg-gradient-to-t from-cyan-200/50 to-transparent animate-wave z-0 pointer-events-none" />
      )}
      {currentMap === 'PARK' && (
        <div className="absolute inset-0 pointer-events-none z-0">
          {particles.slice(0, 8).map(p => (
            <div key={p.id} className="absolute text-pink-200/40 animate-float" 
                 style={{ left: `${p.left}%`, top: `${Math.random() * 100}%`, animationDuration: `${p.duration}s`, fontSize: `${p.size}px` }}>🌸</div>
          ))}
        </div>
      )}

      {currentMap === 'HOME' && currentPet?.homeBackground && (
        <div className="absolute inset-0 z-0 overflow-hidden pointer-events-none opacity-25">
          <img src={currentPet.homeBackground} className="w-full h-full object-cover grayscale-[0.05]" alt="Home" />
        </div>
      )}

      {pets.length === 0 || isUploadingNew ? (
        <div className="flex flex-col items-center justify-center h-full px-6 text-center z-10 relative">
          <div className="mb-10 animate-float">
            <div className="bg-white/80 p-8 rounded-[3rem] shadow-2xl border-4 border-amber-100/50">
              <Sparkles className={`w-20 h-20 text-amber-500 ${is3DGenerating ? 'animate-spin' : ''}`} />
            </div>
          </div>
          <h1 className="text-4xl font-black text-amber-950 mb-4 tracking-tighter">彩虹桥：禅意港湾</h1>
          <p className="text-amber-800/70 mb-12 max-w-sm text-lg font-medium leading-relaxed">
            {is3DGenerating ? "正在通过思念重塑伙伴..." : "上传照片，在这道永恒的彩虹下，重建你们的温馨港湾。"}
          </p>
          {!is3DGenerating && <Pixelator onComplete={handlePetCreated} />}
          {pets.length > 0 && <button onClick={() => setIsUploadingNew(false)} className="mt-6 text-amber-900/50 font-bold underline">返回家园</button>}
        </div>
      ) : (
        <div className="relative w-full h-full">
          {/* Pet Switcher / HUD */}
          <div className="absolute top-8 right-8 flex flex-col items-end gap-3 z-30">
            {pets.map((p, i) => (
              <button key={p.id} onClick={() => handlePetInteract(i)} 
                className={`flex items-center gap-3 px-4 py-2 rounded-2xl transition-all border shadow-sm backdrop-blur-md
                  ${i === activePetIndex ? 'bg-amber-400 text-white border-white scale-105' : 'bg-white/40 text-amber-950 border-white/30 hover:bg-white/60'}`}
              >
                <div className="w-8 h-8 rounded-full overflow-hidden border-2 border-white shadow-sm">
                  <img src={p.hdArt || p.pixelArt} className="w-full h-full object-cover" alt="" />
                </div>
                <span className="text-sm font-black tracking-tight">{p.name}</span>
                {i === activePetIndex && <Edit2 className="w-3 h-3 cursor-pointer" onClick={(e) => { e.stopPropagation(); setIsNamingOpen(true); setNewName(p.name); }} />}
              </button>
            ))}
            {pets.length < 3 && (
              <button onClick={() => setIsUploadingNew(true)} className="flex items-center gap-2 bg-white/20 hover:bg-white/40 backdrop-blur-md px-4 py-2 rounded-2xl text-amber-950/50 text-xs font-bold border border-white/30 transition-all">
                <PlusCircle className="w-4 h-4" /> 添加伙伴
              </button>
            )}
          </div>

          <div className="absolute top-8 left-8 flex items-center gap-3 z-30">
             <div className="bg-white/40 backdrop-blur-md px-4 py-2 rounded-2xl border border-white/40 flex items-center gap-3 shadow-sm">
               {isNight ? <Moon className="w-5 h-5 text-indigo-400" /> : <Sun className="w-5 h-5 text-amber-500" />}
               <span className="font-black text-[10px] tracking-widest text-amber-950 uppercase">{new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>
               <button onClick={() => setIsMuted(!isMuted)} className="p-1">
                 {isMuted ? <VolumeX className="w-4 h-4 text-red-400" /> : <Volume2 className="w-4 h-4 text-emerald-500" />}
               </button>
             </div>
          </div>

          {/* Main Map Content */}
          <div className="relative w-full h-full">
            {currentMap === 'HOME' && (
              <div className="absolute inset-0 flex items-center justify-center">
                 <div className="absolute top-32 left-8 flex flex-col gap-4 z-30">
                   <button onClick={() => setIsToyBoxOpen(!isToyBoxOpen)} className="w-14 h-14 bg-white/70 backdrop-blur-xl rounded-2xl flex items-center justify-center text-amber-900 shadow-xl border-2 border-white hover:scale-110 active:scale-95 transition-all">
                      <Box className="w-6 h-6" />
                   </button>
                   <button onClick={() => homeBgInputRef.current?.click()} className="w-14 h-14 bg-white/70 backdrop-blur-xl rounded-2xl flex items-center justify-center text-amber-900 shadow-xl border-2 border-white hover:scale-110 active:scale-95 transition-all">
                      <Camera className="w-6 h-6" />
                   </button>
                   <input type="file" ref={homeBgInputRef} className="hidden" accept="image/*" onChange={(e) => {
                     const f = e.target.files?.[0];
                     if(f) {
                       const r = new FileReader();
                       r.onload = (ev) => setPets(prev => prev.map((p, i) => i === activePetIndex ? {...p, homeBackground: ev.target?.result as string} : p));
                       r.readAsDataURL(f);
                     }
                   }} />
                 </div>

                 {(currentPet?.toys || []).map(toy => (
                   <div key={toy.id} className="absolute z-10 animate-float" style={{ left: `${toy.x}%`, top: `${toy.y}%` }}>
                      <div className="relative group hover:scale-125 transition-transform cursor-pointer">
                        <span className="text-4xl filter drop-shadow-lg">
                          {toyTypes.find(t => t.type === toy.type)?.icon}
                        </span>
                        <button onClick={() => removeToy(toy.id)} className="absolute -top-4 -right-4 bg-red-400 text-white rounded-full w-6 h-6 flex items-center justify-center text-[10px] opacity-0 group-hover:opacity-100 transition-opacity"><Trash2 className="w-3 h-3"/></button>
                      </div>
                   </div>
                 ))}

                 <button onClick={() => setCurrentMap('SHRINE')} className="absolute bottom-[25%] left-[10%] group transition-all z-20">
                    <div className="relative w-32 h-44 flex flex-col items-center justify-center bg-white/60 backdrop-blur-xl rounded-t-full border-4 border-white shadow-3xl">
                      <Flower className="w-14 h-14 text-amber-400 group-hover:scale-110 transition-transform" />
                      <span className="text-[10px] font-black text-amber-900/40 uppercase tracking-[0.3em] mt-3">禅意之所</span>
                    </div>
                 </button>

                 <div className="absolute bottom-[35%] right-[8%] w-44 h-56 bg-white rounded-3xl shadow-3xl p-5 -rotate-6 border-[10px] border-amber-50 transition-all hover:rotate-0 hover:scale-105 z-10">
                    <div className="w-full h-full overflow-hidden rounded-2xl bg-amber-50">
                      <img src={currentPet?.hdArt || currentPet?.pixelArt} className="w-full h-full object-cover grayscale-[0.05]" alt="" />
                    </div>
                 </div>
              </div>
            )}

            {/* Map Specific Events */}
            {(mapEvents[currentMap] || []).map(event => (
              <button 
                key={event.id}
                onClick={() => handleEventClick(event)}
                className="absolute z-10 text-3xl hover:scale-150 transition-all animate-bounce"
                style={{ left: `${event.x}%`, top: `${event.y}%` }}
              >
                {event.icon}
              </button>
            ))}

            {currentMap === 'SHRINE' && (
               <div className="absolute inset-0 z-40 bg-white/10 backdrop-blur-3xl flex items-center justify-center p-8 animate-in zoom-in duration-1000">
                  <div className="relative w-full max-w-sm bg-white/95 rounded-[5rem] border-[12px] border-white shadow-2xl p-12 flex flex-col items-center">
                    <button onClick={() => setCurrentMap('HOME')} className="absolute top-12 right-14 text-amber-950/20 text-4xl font-black hover:text-amber-950">✕</button>
                    <div className="w-48 h-48 rounded-full border-8 border-white shadow-xl overflow-hidden mb-10">
                      <img src={currentPet?.hdArt || currentPet?.pixelArt} className="w-full h-full object-cover" alt="" />
                    </div>
                    <h3 className="text-3xl font-black text-amber-950 flex items-center gap-4 mb-8"><Flower className="w-10 h-10 text-amber-400" /> 禅修共鸣</h3>
                    <p className="text-[12px] text-center text-amber-900/40 italic mb-12 leading-relaxed font-bold px-4">“在一支清香中，思念跨越生死，化作彼岸的清风。”</p>
                    <button onClick={() => { audio.playSFX('pray'); setStats(prev => ({...prev, peace: 100})); setIsPraying(true); setTimeout(() => setIsPraying(false), 5000); }} disabled={isPraying} className={`px-16 py-7 rounded-[3rem] bg-gradient-to-tr from-amber-400 to-orange-400 text-white font-black shadow-2xl transition-all active:scale-95 ${isPraying ? 'animate-pulse grayscale' : 'hover:-translate-y-2'}`}>
                      {isPraying ? '静心冥想中...' : '开启心灵共鸣'}
                    </button>
                  </div>
               </div>
            )}

            {/* Pets Display with Horizontal Thoughts */}
            {currentMap !== 'SHRINE' && pets.map((p, i) => (
              <div key={p.id} className="absolute transition-all duration-3000 ease-in-out z-20" 
                style={{ left: `${petPositions[i]?.x}%`, top: `${petPositions[i]?.y}%`, transform: 'translate(-50%, -50%)', opacity: i === activePetIndex ? 1 : 0.8 }}
                onClick={() => handlePetInteract(i)}
              >
                {petThoughts[p.id] && (
                  <div className="absolute -top-24 left-1/2 -translate-x-1/2 bg-white/95 backdrop-blur-3xl px-8 py-4 rounded-[2rem] text-sm font-black text-amber-950 shadow-2xl whitespace-nowrap animate-in slide-in-from-bottom-10 duration-500 border-2 border-amber-50 flex items-center justify-center min-w-[120px]">
                    {petThoughts[p.id]}
                    <div className="absolute bottom-0 left-1/2 -translate-x-1/2 translate-y-full w-0 h-0 border-l-[12px] border-l-transparent border-r-[12px] border-r-transparent border-t-[14px] border-t-white/95" />
                  </div>
                )}
                <Pet3D pixelImage={p.pixelArt} hdImage={p.hdArt} isNight={isNight} animation={i === activePetIndex ? 'walking' : 'idle'} />
              </div>
            ))}
          </div>

          <GameUI 
            stats={stats} currentMap={currentMap} onNavigate={m => { audio.playSFX('click'); setCurrentMap(m); }}
            onFeed={food => {
              audio.playSFX('chew');
              setStats(prev => ({ ...prev, hunger: Math.min(100, prev.hunger + food.hungerBoost), mood: Math.min(100, prev.mood + 5) }));
              if (currentPet) {
                setPetThoughts(prev => ({ ...prev, [currentPet.id]: "最喜欢这个了！谢谢~" }));
                setTimeout(() => setPetThoughts(prev => ({ ...prev, [currentPet.id]: null })), 4000);
              }
            }}
            onOpenJournal={() => { audio.playSFX('click'); setIsJournalOpen(true); }}
            petName={currentPet?.name || ''}
          />
        </div>
      )}

      {/* Modals */}
      {isToyBoxOpen && (
        <div className="fixed inset-0 z-[110] bg-black/20 backdrop-blur-md flex items-center justify-center p-6 animate-in zoom-in duration-500">
          <div className="bg-white/95 backdrop-blur-2xl rounded-[4rem] p-12 w-full max-w-sm shadow-3xl border-8 border-amber-100/50">
            <h3 className="text-3xl font-black text-amber-950 mb-10 flex items-center gap-4"><Box className="w-10 h-10 text-amber-500" /> 温馨玩具箱</h3>
            <div className="grid grid-cols-3 gap-5">
              {toyTypes.map(t => (
                <button key={t.type} onClick={() => addToy(t.type)} className="aspect-square bg-amber-50/50 rounded-3xl flex flex-col items-center justify-center gap-2 hover:bg-amber-100 transition-all border-2 border-amber-100/20 group">
                  <span className="text-4xl group-hover:scale-110 transition-transform">{t.icon}</span>
                  <span className="text-[9px] font-black text-amber-900/40 uppercase tracking-tighter">{t.label}</span>
                </button>
              ))}
            </div>
            <button onClick={() => setIsToyBoxOpen(false)} className="w-full mt-12 py-5 rounded-2xl font-black text-amber-900 bg-amber-100 hover:bg-amber-200 transition-colors">关闭</button>
          </div>
        </div>
      )}

      {isNamingOpen && (
        <div className="fixed inset-0 z-[120] bg-black/40 backdrop-blur-2xl flex items-center justify-center p-6 animate-in fade-in duration-300">
          <div className="bg-white rounded-[4rem] p-12 w-full max-w-sm shadow-3xl border-[12px] border-amber-100/50 text-center">
            <h3 className="text-2xl font-black text-amber-950 mb-10 flex items-center justify-center gap-4"><Edit2 className="w-8 h-8 text-amber-500" /> 修改名称</h3>
            <input type="text" value={newName} onChange={e => setNewName(e.target.value)} className="w-full bg-amber-50/50 border-4 border-amber-100 rounded-2xl px-8 py-5 text-2xl font-black text-amber-950 text-center mb-12 focus:outline-none focus:border-amber-300 transition-all" autoFocus />
            <div className="flex gap-4">
              <button onClick={() => setIsNamingOpen(false)} className="flex-1 px-8 py-5 rounded-2xl font-black text-amber-900 bg-amber-100 hover:bg-amber-200 transition-colors">取消</button>
              <button onClick={handleRename} className="flex-2 px-10 py-5 rounded-2xl font-black text-white bg-amber-500 hover:bg-amber-600 shadow-xl transition-all">确认</button>
            </div>
          </div>
        </div>
      )}

      {isJournalOpen && (
        <div className="fixed inset-0 z-50 bg-black/30 backdrop-blur-3xl flex items-center justify-center p-6 animate-in fade-in duration-1000">
          <div className="bg-amber-50/95 w-full max-w-xl h-[85vh] rounded-[5rem] shadow-3xl overflow-hidden flex flex-col border-[14px] border-white">
            <div className="p-14 bg-gradient-to-tr from-amber-400 to-orange-400 text-white flex justify-between items-center shadow-2xl relative z-10">
              <div className="flex items-center gap-6"><BookOpen className="w-16 h-16" /><div><h3 className="text-4xl font-black tracking-tighter">时光回响</h3><p className="text-[12px] font-black uppercase tracking-[0.5em] opacity-80">Eternal Memories</p></div></div>
              <button onClick={() => setIsJournalOpen(false)} className="w-16 h-16 rounded-[2rem] bg-white/20 flex items-center justify-center font-black text-3xl hover:bg-white/30 transition-all active:scale-90">✕</button>
            </div>
            <div className="flex-1 overflow-y-auto p-14 space-y-14 scrollbar-hide bg-amber-50/30">
              {journal.map((e, idx) => (
                <div key={idx} className="p-12 rounded-[4rem] bg-white border-4 border-amber-50 shadow-sm transition-all hover:-translate-y-2 hover:shadow-xl">
                  <span className="text-[11px] font-black text-amber-900/30 uppercase tracking-[0.4em] block mb-6">{e.date}</span>
                  <p className="text-amber-950 italic leading-relaxed text-xl font-black">“{e.content}”</p>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

