// Helper for exponential backoff
const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

async function callGeminiWithRetry(fn: () => Promise<any>, maxRetries = 3): Promise<any> {
  let lastError: any;
  for (let i = 0; i < maxRetries; i++) {
    try {
      return await fn();
    } catch (error: any) {
      lastError = error;
      // If it's a rate limit error (429), wait and retry
      if (error?.status === 429 || error?.message?.includes('429') || error?.message?.includes('RESOURCE_EXHAUSTED')) {
        const waitTime = Math.pow(2, i) * 1000 + Math.random() * 1000;
        console.warn(`Gemini API rate limited. Retrying in ${Math.round(waitTime)}ms... (Attempt ${i + 1}/${maxRetries})`);
        await sleep(waitTime);
        continue;
      }
      // For other errors, throw immediately
      throw error;
    }
  }
  throw lastError;
}

export async function identifyPet(imageBase64: string): Promise<'cat' | 'dog' | 'bird' | 'other'> {
  // Create a new instance right before use to ensure the latest API key is used
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await callGeminiWithRetry(() => ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { text: "Identify the pet species in this image. Respond with ONLY one word from this list: 'cat', 'dog', 'bird', 'other'." },
          {
            inlineData: {
              mimeType: "image/png",
              data: imageBase64.split(',')[1]
            }
          }
        ]
      }
    }));

    const result = response.text?.trim().toLowerCase();
    if (result?.includes('cat')) return 'cat';
    if (result?.includes('dog')) return 'dog';
    if (result?.includes('bird')) return 'bird';
    return 'other';
  } catch (error) {
    console.error("Gemini Identification Error after retries:", error);
    // Silent fallback to avoid breaking the UX flow
    return 'other';
  }
}

